insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('e6000000-0000-0000-0000-000000000001', 'ukmla', 'd04b73d2-a652-4845-9ad5-10fe8667988d',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('e6000000-0000-0000-0000-000000000001', 'A', 'Rheumatoid factor', false, 'Ruled out because rheumatoid factor is neither sensitive nor specific for SLE; it is more relevant to rheumatoid arthritis and can be positive in many other conditions, so it would not help confirm this diagnosis.', 1),
('e6000000-0000-0000-0000-000000000001', 'B', 'Anti-cyclic citrullinated peptide (anti-CCP) antibody', false, 'Ruled out because anti-CCP antibodies are specific for rheumatoid arthritis, not SLE, and would not support or refute the diagnosis suggested by this clinical picture.', 2),
('e6000000-0000-0000-0000-000000000001', 'C', 'HLA-B27 typing', false, 'Ruled out because HLA-B27 is associated with seronegative spondyloarthropathies (e.g. ankylosing spondylitis), not connective tissue disease with a malar rash and cytopenias.', 3),
('e6000000-0000-0000-0000-000000000001', 'D', 'Uric acid level', false, 'Ruled out because a raised uric acid level would support gout, which does not explain photosensitive malar rash, oral ulcers, and cytopenias; it has no diagnostic role here.', 4),
('e6000000-0000-0000-0000-000000000001', 'E', 'Anti-double-stranded DNA (anti-dsDNA) antibody titre', true, 'Correct. This presentation (malar rash, photosensitivity, oral ulcers, non-erosive arthritis, cytopenias, positive ANA) is classic for systemic lupus erythematosus (SLE). Anti-dsDNA is highly specific for SLE and its titre correlates with disease activity, particularly renal involvement, making it the most useful confirmatory test.', 5),
('e6000000-0000-0000-0000-000000000002', 'A', 'Haemophilia A', false, 'Ruled out because haemophilia A causes bleeding due to factor VIII deficiency; it does not cause thrombosis or recurrent miscarriage, and mixing studies would correct the APTT rather than fail to correct.', 1),
('e6000000-0000-0000-0000-000000000002', 'B', 'Disseminated intravascular coagulation', false, 'Ruled out because DIC is an acute consumptive coagulopathy with widespread bleeding and clotting, low fibrinogen, and raised D-dimer in the context of an acute critical illness, not a chronic pattern of recurrent miscarriage and antiphospholipid antibody positivity.', 2),
('e6000000-0000-0000-0000-000000000002', 'C', 'Protein C deficiency', false, 'Ruled out because protein C deficiency causes a hereditary prothrombotic state but does not explain a non-correcting mixing study or antiphospholipid antibody positivity, and is not classically associated with recurrent first-trimester miscarriage.', 3),
('e6000000-0000-0000-0000-000000000002', 'D', 'Antiphospholipid syndrome', true, 'Correct. Recurrent pregnancy loss, unprovoked venous thrombosis, a paradoxically prolonged APTT that fails to correct on mixing (reflecting an in-vitro inhibitor rather than a factor deficiency), and persistent antiphospholipid antibodies (lupus anticoagulant, anticardiolipin) on two occasions 12 weeks apart fulfil the diagnostic criteria for antiphospholipid syndrome, which occurs commonly alongside SLE.', 4),
('e6000000-0000-0000-0000-000000000002', 'E', 'Factor V Leiden mutation', false, 'Ruled out because Factor V Leiden is a common inherited thrombophilia detected by genetic/functional assay, not by antiphospholipid antibodies, and does not explain a non-correcting APTT mixing study.', 5),
('e6000000-0000-0000-0000-000000000003', 'A', 'High-dose oral corticosteroids', false, 'Ruled out because high-dose corticosteroids are a recognised precipitant of scleroderma renal crisis and can worsen it; they are not the treatment for this complication.', 1),
('e6000000-0000-0000-0000-000000000003', 'B', 'Reassurance and outpatient rheumatology follow-up in 6 weeks', false, 'Ruled out because scleroderma renal crisis is a medical emergency that can rapidly progress to irreversible renal failure; it requires urgent inpatient treatment, not deferred outpatient review.', 2),
('e6000000-0000-0000-0000-000000000003', 'C', 'Urgent initiation of an ACE inhibitor with close monitoring of blood pressure and renal function', true, $x$Correct. This is scleroderma (systemic sclerosis) with Raynaud's phenomenon, skin tightening (sclerodactyly) and microstomia, now complicated by scleroderma renal crisis (malignant hypertension, acute kidney injury, microangiopathic haemolysis with schistocytes). ACE inhibitors are the specific first-line treatment for scleroderma renal crisis, started urgently even before renal function is fully characterised, as delay risks irreversible renal failure.$x$, 3),
('e6000000-0000-0000-0000-000000000003', 'D', $x$Calcium channel blocker alone for Raynaud's symptom control$x$, false, $x$Ruled out because while calcium channel blockers help Raynaud's phenomenon, they do not address the emergency of malignant hypertension and acute kidney injury from renal crisis, for which ACE inhibitors are specifically indicated.$x$, 4),
('e6000000-0000-0000-0000-000000000003', 'E', 'Intravenous furosemide to improve urine output', false, 'Ruled out because diuretics do not address the underlying renin-mediated vasculopathy causing scleroderma renal crisis and do not replace urgent ACE inhibition.', 5),
('e6000000-0000-0000-0000-000000000004', 'A', 'Increased risk of non-Hodgkin lymphoma', true, $x$Correct. This is primary Sjogren's syndrome (sicca symptoms of dry eyes and dry mouth with positive anti-Ro/anti-La antibodies). Patients with Sjogren's syndrome have a significantly increased lifetime risk of B-cell non-Hodgkin lymphoma (particularly of the parotid/salivary glands), and should be advised to report persistent parotid swelling or lymphadenopathy.$x$, 1),
('e6000000-0000-0000-0000-000000000004', 'B', 'Increased risk of pulmonary embolism', false, $x$Ruled out because Sjogren's syndrome is not classically associated with a prothrombotic state in the way that antiphospholipid syndrome is; venous thromboembolism is not the key long-term complication to counsel about here.$x$, 2),
('e6000000-0000-0000-0000-000000000004', 'C', 'Increased risk of avascular necrosis of the hip', false, $x$Ruled out because avascular necrosis is associated with corticosteroid use, alcohol excess, or sickle cell disease, not specifically with Sjogren's syndrome itself.$x$, 3),
('e6000000-0000-0000-0000-000000000004', 'D', 'Increased risk of gouty arthritis', false, $x$Ruled out because gout results from hyperuricaemia and monosodium urate crystal deposition, which is unrelated to the autoimmune sicca syndrome and lymphoproliferative risk of Sjogren's syndrome.$x$, 4),
('e6000000-0000-0000-0000-000000000004', 'E', 'Increased risk of osteoporotic fracture', false, $x$Ruled out because while long-term steroid use in any rheumatic disease can contribute to osteoporosis, this is not the specific, well-recognised complication uniquely linked to Sjogren's syndrome that patients should be counselled about.$x$, 5),
('e6000000-0000-0000-0000-000000000005', 'A', 'Slit-lamp examination for anterior uveitis', false, 'Ruled out because anterior uveitis is associated with seronegative spondyloarthropathies (e.g. ankylosing spondylitis), not with dermatomyositis, so it is not the priority additional assessment here.', 1),
('e6000000-0000-0000-0000-000000000005', 'B', 'Age-appropriate malignancy screening', true, $x$Correct. This presentation (proximal myopathy, raised CK, periorbital heliotrope rash, and Gottron's papules over the knuckles) is classic for dermatomyositis. Dermatomyositis has a well-established association with underlying malignancy (paraneoplastic), particularly in adults over 40, so thorough age- and sex-appropriate cancer screening is an essential part of the initial work-up alongside immunosuppressive treatment.$x$, 2),
('e6000000-0000-0000-0000-000000000005', 'C', 'HLA-B27 typing', false, 'Ruled out because HLA-B27 is relevant to spondyloarthropathies, not to inflammatory myopathies such as dermatomyositis, and would not change management.', 3),
('e6000000-0000-0000-0000-000000000005', 'D', '24-hour urinary free cortisol', false, $x$Ruled out because this test screens for Cushing's syndrome, which is not suggested by this clinical picture and is not the recognised association requiring screening in dermatomyositis.$x$, 4),
('e6000000-0000-0000-0000-000000000005', 'E', 'Nerve conduction studies of the lower limbs', false, 'Ruled out because the weakness pattern here (proximal, symmetrical, with a raised CK and characteristic rash) points to a myopathic rather than a neuropathic process, so nerve conduction studies are not the priority investigation.', 5),
('e6000000-0000-0000-0000-000000000006', 'A', 'Start high-dose intravenous cyclophosphamide', false, 'Ruled out because cyclophosphamide is reserved for severe organ-threatening lupus (e.g. renal or CNS involvement) which is not present here; drug-induced lupus is generally mild and managed by withdrawing the causative drug.', 1),
('e6000000-0000-0000-0000-000000000006', 'B', 'Continue hydralazine and add hydroxychloroquine', false, 'Ruled out because continuing the offending drug will perpetuate the drug-induced lupus syndrome; the causative agent should be stopped, not continued alongside additional immunosuppression.', 2),
('e6000000-0000-0000-0000-000000000006', 'C', 'Stop hydralazine and monitor symptoms', true, 'Correct. This presentation (arthralgia, pleuritic chest pain, positive ANA and anti-histone antibodies, negative anti-dsDNA, and typically absence of renal involvement) in a patient on a known culprit drug is classic for drug-induced lupus. Symptoms usually resolve over weeks to months after stopping the offending drug, and this is the key initial management step before considering any other treatment.', 3),
('e6000000-0000-0000-0000-000000000006', 'D', 'Arrange renal biopsy immediately', false, 'Ruled out because renal function and urinalysis are normal, so there is no indication of renal involvement requiring biopsy at this stage.', 4),
('e6000000-0000-0000-0000-000000000006', 'E', 'Reassure the patient that this is unrelated to his medication and no action is needed', false, 'Ruled out because the clinical and serological pattern (arthralgia, serositis, anti-histone antibodies, negative anti-dsDNA on a known culprit drug) strongly suggests a causal drug-induced lupus syndrome that requires action, not reassurance without intervention.', 5),
('e6000000-0000-0000-0000-000000000007', 'A', 'Serum urate level alone, without joint aspiration', false, 'Ruled out because serum urate can be normal during an acute gout flare and can also be raised in asymptomatic hyperuricaemia, so it is neither sensitive nor specific enough alone; joint aspiration remains essential, particularly to exclude septic arthritis.', 1),
('e6000000-0000-0000-0000-000000000007', 'B', 'Joint aspiration for synovial fluid microscopy (looking for negatively birefringent needle-shaped crystals) and culture', true, 'Correct. This presentation (acute monoarthritis of the first MTP joint, thiazide diuretic use, alcohol excess) is highly suggestive of gout, but joint aspiration is essential both to confirm monosodium urate crystals under polarised light microscopy and, critically, to exclude septic arthritis by Gram stain and culture, since the two can look identical clinically and septic arthritis must never be missed.', 2),
('e6000000-0000-0000-0000-000000000007', 'C', 'Plain X-ray of the foot', false, 'Ruled out because X-ray changes of chronic gout (erosions, tophi) take months to years to develop and are usually normal in a first acute attack; it would not confirm the diagnosis or exclude septic arthritis, which is the key differential to rule out.', 3),
('e6000000-0000-0000-0000-000000000007', 'D', 'Rheumatoid factor and anti-CCP antibodies', false, 'Ruled out because these are relevant to rheumatoid arthritis, which typically causes a symmetrical small-joint polyarthritis rather than acute monoarthritis of the first MTP joint.', 4),
('e6000000-0000-0000-0000-000000000007', 'E', 'Reassurance and empirical NSAID without further investigation', false, 'Ruled out because treating empirically without joint aspiration risks missing septic arthritis, which requires urgent antibiotics and orthopaedic input rather than anti-inflammatory treatment alone; any acute hot swollen joint should have septic arthritis actively excluded.', 5),
('e6000000-0000-0000-0000-000000000008', 'A', 'A short course of oral corticosteroids', true, 'Correct. In a patient with significant renal impairment (eGFR 32) and cardiovascular disease, NSAIDs should be avoided (nephrotoxic, and risk of fluid retention/cardiovascular events), and colchicine also requires significant dose reduction with increased toxicity risk in renal impairment. A short course of oral corticosteroids (e.g. prednisolone) is an effective and appropriate first-line option for acute gout in this context.', 1),
('e6000000-0000-0000-0000-000000000008', 'B', 'High-dose ibuprofen', false, 'Ruled out because NSAIDs are nephrotoxic and can worsen renal function further in a patient with CKD stage 3b, and also carry cardiovascular risk in a patient with ischaemic heart disease, making them an unsafe choice here.', 2),
('e6000000-0000-0000-0000-000000000008', 'C', 'Standard-dose colchicine 500 micrograms four times daily for one week', false, 'Ruled out because colchicine is renally excreted and accumulates in significant renal impairment, markedly increasing the risk of toxicity (including bone marrow suppression and neuromyotoxicity); doses must be substantially reduced or avoided rather than given at standard dosing.', 3),
('e6000000-0000-0000-0000-000000000008', 'D', 'Start allopurinol immediately at a high dose to lower urate quickly', false, 'Ruled out because urate-lowering therapy should not be initiated during an acute gout flare, as it can prolong or worsen the acute attack; when started, it should begin at a low dose after the acute attack has settled, with anti-inflammatory cover.', 4),
('e6000000-0000-0000-0000-000000000008', 'E', 'Intravenous unfractionated heparin', false, 'Ruled out because anticoagulation has no role in the treatment of an acute gout attack; this is not a thrombotic process.', 5),
('e6000000-0000-0000-0000-000000000009', 'A', 'Gout', false, 'Ruled out because gout is caused by negatively birefringent needle-shaped monosodium urate crystals, not positively birefringent rhomboid crystals, and does not classically cause chondrocalcinosis on X-ray.', 1),
('e6000000-0000-0000-0000-000000000009', 'B', 'Septic arthritis', false, 'Ruled out because no organisms were seen on Gram stain and the crystal findings are diagnostic of pseudogout; septic arthritis should always be considered but is not supported by these results.', 2),
('e6000000-0000-0000-0000-000000000009', 'C', 'Osteoarthritis', false, 'Ruled out because osteoarthritis is a chronic degenerative process that does not typically present with acute hot joint swelling or crystals on aspiration, though chondrocalcinosis can coexist with OA.', 3),
('e6000000-0000-0000-0000-000000000009', 'D', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis causes a symmetrical inflammatory small-joint polyarthritis rather than acute monoarthritis with crystal-positive aspirate and chondrocalcinosis.', 4),
('e6000000-0000-0000-0000-000000000009', 'E', 'Calcium pyrophosphate deposition disease (pseudogout)', true, 'Correct. Acute monoarthritis in an elderly patient, with radiographic chondrocalcinosis (linear cartilage calcification) and positively birefringent rhomboid-shaped crystals on synovial fluid analysis, is diagnostic of calcium pyrophosphate deposition disease, commonly called pseudogout. It is associated with older age and metabolic conditions such as hyperparathyroidism, haemochromatosis, and hypothyroidism.', 5),
('e6000000-0000-0000-0000-000000000010', 'A', 'Start allopurinol at a high dose immediately without titration', false, 'Ruled out because starting allopurinol at a high dose risks a more severe hypersensitivity reaction and does not follow the recommended start-low-titrate-slow approach used to minimise flare risk and adverse effects.', 1),
('e6000000-0000-0000-0000-000000000010', 'B', 'Advise no medication is needed as the attack has already settled', false, $x$Ruled out because recurrent gout flares (three attacks in 18 months) with a persistently elevated urate level is an indication for urate-lowering therapy to prevent further attacks and long-term joint damage, not a 'watch and wait' approach.$x$, 2),
('e6000000-0000-0000-0000-000000000010', 'C', 'Start allopurinol during a future acute flare, not now', false, 'Ruled out because starting urate-lowering therapy during an acute flare can worsen or prolong the attack; the correct time to initiate it is during a quiescent, symptom-free interval, as is the case now.', 3),
('e6000000-0000-0000-0000-000000000010', 'D', 'Start allopurinol at a low dose, titrating upward with monitoring of serum urate, alongside colchicine cover', true, 'Correct. This patient has recurrent gout flares and is now in a symptom-free interval, which is the appropriate time to start urate-lowering therapy. Allopurinol is first-line, started at a low dose and titrated against serum urate levels (target typically below 300 micromol/L), with colchicine or NSAID cover for the first weeks to reduce the risk of a precipitated flare.', 4),
('e6000000-0000-0000-0000-000000000010', 'E', 'Start colchicine as long-term monotherapy for urate lowering', false, 'Ruled out because colchicine is an anti-inflammatory agent used for acute attacks or as short-term prophylaxis when starting urate-lowering therapy; it does not lower serum urate and does not address the underlying hyperuricaemia.', 5),
('e6000000-0000-0000-0000-000000000011', 'A', 'Oral NSAIDs and review in the outpatient rheumatology clinic in 2 weeks', false, 'Ruled out because this delay and lack of source control risks irreversible joint destruction and sepsis if this is septic arthritis, which must be treated as a same-day emergency.', 1),
('e6000000-0000-0000-0000-000000000011', 'B', 'Colchicine, as this is likely to be an acute gout flare', false, 'Ruled out because assuming gout without excluding septic arthritis in a febrile, systemically unwell patient is dangerous; septic arthritis must be actively excluded first given the risk of joint destruction and sepsis.', 2),
('e6000000-0000-0000-0000-000000000011', 'C', 'Discharge with safety-net advice and GP follow-up in one week', false, 'Ruled out because a hot swollen joint with fever and systemic illness requires same-day emergency assessment and treatment, not discharge with delayed follow-up.', 3),
('e6000000-0000-0000-0000-000000000011', 'D', 'Physiotherapy referral for joint mobilisation', false, 'Ruled out because physiotherapy is inappropriate and potentially harmful in a suspected septic joint, which requires urgent medical/surgical treatment, not mobilisation exercises.', 4),
('e6000000-0000-0000-0000-000000000011', 'E', 'Urgent joint aspiration for microscopy, Gram stain, and culture, with empirical intravenous antibiotics started without delay', true, 'Correct. A hot, swollen, systemically unwell patient with fever and a diabetic background (increased infection risk) must be treated as septic arthritis until proven otherwise. This is an orthopaedic emergency: urgent joint aspiration to guide diagnosis should not delay starting empirical intravenous antibiotics, and orthopaedic review for possible washout is required.', 5),
('e6000000-0000-0000-0000-000000000012', 'A', 'Febuxostat commonly causes irreversible peripheral neuropathy', false, 'Ruled out because peripheral neuropathy is not a recognised major adverse effect of febuxostat; the key safety signal is increased cardiovascular mortality risk in patients with pre-existing cardiovascular disease.', 1),
('e6000000-0000-0000-0000-000000000012', 'B', 'Febuxostat carries an increased risk of cardiovascular death compared with allopurinol in patients with pre-existing cardiovascular disease', true, 'Correct. Febuxostat has been associated with a significantly increased risk of cardiovascular death compared with allopurinol in patients with a history of major cardiovascular disease. In a patient with a prior myocardial infarction, this risk must be carefully discussed and febuxostat used only if no suitable alternative exists, with close monitoring.', 2),
('e6000000-0000-0000-0000-000000000012', 'C', 'Febuxostat requires no dose adjustment or monitoring in renal impairment, unlike allopurinol', false, 'Ruled out because this is not the primary safety concern for this patient, and febuxostat still requires appropriate caution and monitoring; the pressing issue here is his established cardiovascular disease.', 3),
('e6000000-0000-0000-0000-000000000012', 'D', 'Febuxostat cannot be used in combination with colchicine', false, 'Ruled out because febuxostat can be co-prescribed with colchicine for flare prophylaxis during initiation; this is not a genuine contraindication and is not the key safety issue in this cardiac patient.', 4),
('e6000000-0000-0000-0000-000000000012', 'E', 'Febuxostat causes hypoglycaemia in patients with diabetes', false, $x$Ruled out because febuxostat is not known to cause hypoglycaemia; this is not a recognised adverse effect and is not relevant to this patient's presentation.$x$, 5),
('e6000000-0000-0000-0000-000000000013', 'A', 'Osteoarthritis', false, $x$Ruled out because osteoarthritis typically causes asymmetrical joint pain worse with activity and better with rest, commonly affects the DIP joints (Heberden's nodes) and first CMC joint, and is not associated with raised inflammatory markers or positive rheumatoid factor/anti-CCP.$x$, 1),
('e6000000-0000-0000-0000-000000000013', 'B', 'Psoriatic arthritis', false, 'Ruled out because there is no mention of psoriasis, nail changes, or dactylitis, and the serological pattern (positive RF and anti-CCP) is more typical of rheumatoid arthritis than psoriatic arthritis, which is usually seronegative.', 2),
('e6000000-0000-0000-0000-000000000013', 'C', 'Rheumatoid arthritis', true, 'Correct. Symmetrical small-joint polyarthritis sparing the DIP joints, with prolonged morning stiffness (>1 hour), raised inflammatory markers, and positive rheumatoid factor and anti-CCP antibodies is the classic presentation of rheumatoid arthritis. Anti-CCP is particularly specific for RA and often predicts a more erosive disease course.', 3),
('e6000000-0000-0000-0000-000000000013', 'D', 'Gout', false, 'Ruled out because gout typically causes acute monoarthritis (classically the first MTP joint) rather than a symmetrical chronic small-joint polyarthritis, and is not associated with positive rheumatoid factor or anti-CCP antibodies.', 4),
('e6000000-0000-0000-0000-000000000013', 'E', 'Systemic lupus erythematosus', false, 'Ruled out because although SLE can cause arthralgia, this clinical and serological pattern (erosive-pattern symmetrical polyarthritis with anti-CCP positivity) is characteristic of rheumatoid arthritis rather than SLE, which would more typically show ANA/anti-dsDNA positivity with other systemic features.', 5),
('e6000000-0000-0000-0000-000000000014', 'A', 'No monitoring is required once the patient is established on a stable dose', false, 'Ruled out because methotrexate can cause delayed haematological and hepatic toxicity even on a stable dose, so ongoing regular monitoring is required for as long as the patient remains on treatment.', 1),
('e6000000-0000-0000-0000-000000000014', 'B', 'Annual chest X-ray only, with no blood test monitoring required', false, 'Ruled out because while pulmonary toxicity is a recognised complication, the mainstay of routine monitoring is regular blood tests (FBC, LFT, renal function); annual chest X-ray alone is not sufficient and blood monitoring must not be omitted.', 2),
('e6000000-0000-0000-0000-000000000014', 'C', 'Daily home urine dipstick testing for protein', false, 'Ruled out because this is not part of standard methotrexate monitoring; the key surveillance is blood-based (FBC, LFTs, renal function), not urine dipstick testing.', 3),
('e6000000-0000-0000-0000-000000000014', 'D', 'Regular full blood count, liver function tests, and renal function, initially every 1-2 weeks until stable, then every 2-3 months', true, 'Correct. Methotrexate requires regular monitoring of FBC (for bone marrow suppression/pancytopenia), liver function tests (for hepatotoxicity), and renal function (methotrexate is renally excreted and accumulates in impairment), with more frequent monitoring during dose titration and less frequent once the patient is on a stable dose.', 4),
('e6000000-0000-0000-0000-000000000014', 'E', 'Weekly HbA1c monitoring', false, 'Ruled out because methotrexate is not known to cause diabetes and HbA1c is not part of its recognised monitoring requirements.', 5),
('e6000000-0000-0000-0000-000000000015', 'A', 'Withhold methotrexate until the infection has fully resolved, then restart once well', true, 'Correct. Methotrexate is immunosuppressive and should be temporarily withheld during acute significant infections (such as pneumonia) to allow the immune system to fight the infection effectively and to avoid additive bone marrow suppression risk if antibiotics affecting blood counts are also needed; it can be safely restarted once the infection has resolved.', 1),
('e6000000-0000-0000-0000-000000000015', 'B', 'Continue methotrexate at the same dose alongside antibiotics', false, 'Ruled out because continuing an immunosuppressive DMARD during an active significant infection can impair the ability to clear the infection and increases the risk of complications; standard practice is to hold the drug temporarily.', 2),
('e6000000-0000-0000-0000-000000000015', 'C', 'Increase the methotrexate dose to help control inflammation from the infection', false, 'Ruled out because increasing an immunosuppressive drug during active infection would worsen, not help, the ability to fight infection, and is not appropriate management.', 3),
('e6000000-0000-0000-0000-000000000015', 'D', 'Stop methotrexate permanently and switch to a biologic immediately', false, 'Ruled out because a single significant infection does not necessitate permanently stopping methotrexate; it can typically be safely restarted once the acute infection has resolved, without needing to switch to biologic therapy at this point.', 4),
('e6000000-0000-0000-0000-000000000015', 'E', 'No change is needed as methotrexate does not affect infection risk', false, 'Ruled out because methotrexate is immunosuppressive and does affect the ability to fight infections, which is precisely why it should be temporarily withheld during a significant acute infection.', 5),
('e6000000-0000-0000-0000-000000000016', 'A', 'Latent tuberculosis infection and viral hepatitis B and C status', true, 'Correct. Anti-TNF biologics significantly increase the risk of reactivating latent tuberculosis and viral hepatitis, which can be life-threatening. Screening (including chest X-ray and interferon-gamma release assay or Mantoux test for TB, plus hepatitis B and C serology) is mandatory before starting anti-TNF therapy, with treatment of latent infection first if identified.', 1),
('e6000000-0000-0000-0000-000000000016', 'B', 'Serum urate level', false, 'Ruled out because serum urate screening is not part of standard pre-biologic work-up and is unrelated to the key infection risks of anti-TNF therapy.', 2),
('e6000000-0000-0000-0000-000000000016', 'C', 'Fasting lipid profile only, with no infection screening required', false, 'Ruled out because while cardiovascular risk factors may be relevant to overall RA management, the critical and mandatory pre-biologic screening is for latent TB and viral hepatitis due to the risk of serious reactivation, which lipid screening does not address.', 3),
('e6000000-0000-0000-0000-000000000016', 'D', 'Bone mineral density scan', false, 'Ruled out because bone density assessment is relevant to steroid-related osteoporosis risk, not to the specific infection reactivation risks that must be screened for before starting anti-TNF therapy.', 4),
('e6000000-0000-0000-0000-000000000016', 'E', 'HLA-B27 typing', false, 'Ruled out because HLA-B27 is relevant to spondyloarthropathy diagnosis, not to biologic safety screening, and does not need to be checked before starting adalimumab.', 5),
('e6000000-0000-0000-0000-000000000017', 'A', 'Chest X-ray only, as this is standard pre-operative practice', false, $x$Ruled out because a routine chest X-ray does not assess cervical spine stability and would not identify atlantoaxial subluxation, which is the specific concern raised by this patient's symptoms.$x$, 1),
('e6000000-0000-0000-0000-000000000017', 'B', 'Doppler ultrasound of the carotid arteries', false, 'Ruled out because carotid Doppler assesses vascular flow, not cervical spine bony stability, and would not detect atlantoaxial subluxation or cord compression risk.', 2),
('e6000000-0000-0000-0000-000000000017', 'C', 'Nerve conduction studies of the upper limbs', false, 'Ruled out because nerve conduction studies assess peripheral nerve function, not cervical spine instability, and would not provide the information needed to plan safe airway management.', 3),
('e6000000-0000-0000-0000-000000000017', 'D', 'Lateral cervical spine X-ray in flexion and extension to assess for atlantoaxial subluxation', true, $x$Correct. Longstanding rheumatoid arthritis can cause erosive damage to the cervical spine, particularly atlantoaxial subluxation, which risks spinal cord compression during neck manipulation for intubation. Lhermitte's-type electric shock sensations on neck flexion are a red flag for this. Flexion-extension lateral cervical spine imaging (or MRI if available) should be performed before any procedure requiring neck manipulation or intubation to guide safe airway management.$x$, 4),
('e6000000-0000-0000-0000-000000000017', 'E', 'No additional imaging is required; proceed with standard intubation technique', false, 'Ruled out because proceeding without assessing for atlantoaxial instability in a patient with symptoms suggestive of cervical myelopathy risks catastrophic spinal cord injury during intubation; imaging must be performed first.', 5),
('e6000000-0000-0000-0000-000000000018', 'A', 'Advise her to simply resume the correct weekly dosing schedule and review in clinic in 4 weeks', false, 'Ruled out because this patient has life-threatening pancytopenia from methotrexate overdose requiring immediate inpatient treatment; outpatient follow-up in 4 weeks would risk death from neutropenic sepsis or bleeding.', 1),
('e6000000-0000-0000-0000-000000000018', 'B', 'Admit for urgent folinic acid (calcium folinate) rescue, supportive care, and haematology input', true, $x$Correct. This is acute methotrexate toxicity from inadvertent daily dosing, causing severe pancytopenia with neutropenic sepsis risk and mucositis. This is a medical emergency requiring urgent admission, folinic acid rescue to counteract methotrexate's antifolate effect, broad-spectrum antibiotics if febrile/neutropenic, blood product support as needed, and haematology/toxicology input.$x$, 2),
('e6000000-0000-0000-0000-000000000018', 'C', $x$Give a higher one-off dose of methotrexate to 'catch up' on the missed weekly dosing pattern$x$, false, 'Ruled out because this would worsen an already severe toxic overdose and is dangerously incorrect; methotrexate must be stopped immediately, not increased.', 3),
('e6000000-0000-0000-0000-000000000018', 'D', 'Start oral folic acid supplementation alone as an outpatient', false, 'Ruled out because standard oral folic acid supplementation (used to reduce routine methotrexate side effects) is not equivalent to folinic acid (leucovorin) rescue, which is specifically required to reverse acute methotrexate toxicity, and outpatient management is unsafe given the severity of pancytopenia.', 4),
('e6000000-0000-0000-0000-000000000018', 'E', 'Reassure her that this will self-resolve without treatment', false, 'Ruled out because severe pancytopenia with neutropenia and mucositis from methotrexate toxicity can be fatal without prompt treatment; this requires urgent active intervention, not reassurance.', 5),
('e6000000-0000-0000-0000-000000000019', 'A', 'Reassurance only, as this is a normal age-related fracture', false, 'Ruled out because a fracture from a fall at standing height (a fragility fracture) combined with a T-score confirming osteoporosis requires active treatment to reduce future fracture risk, not reassurance alone.', 1),
('e6000000-0000-0000-0000-000000000019', 'B', 'Long-term high-dose oral corticosteroids', false, 'Ruled out because corticosteroids do not treat osteoporosis and are in fact a major risk factor for causing it; they would worsen bone density, not improve it.', 2),
('e6000000-0000-0000-0000-000000000019', 'C', 'Calcitonin as first-line monotherapy', false, 'Ruled out because calcitonin is not a first-line treatment for osteoporosis and has a much weaker evidence base and greater side-effect profile compared with bisphosphonates.', 3),
('e6000000-0000-0000-0000-000000000019', 'D', 'Immediate parathyroidectomy', false, 'Ruled out because there is no indication of primary hyperparathyroidism in this vignette; surgery is not indicated for postmenopausal osteoporosis.', 4),
('e6000000-0000-0000-0000-000000000019', 'E', 'Oral alendronic acid, alongside calcium and vitamin D supplementation if dietary intake is inadequate', true, 'Correct. A T-score of -2.7 confirms osteoporosis (T-score less than or equal to -2.5), and a fragility fracture (from standing height) in this context confirms the diagnosis clinically. Oral bisphosphonates such as alendronic acid are first-line treatment to reduce future fracture risk, alongside ensuring adequate calcium and vitamin D status.', 5),
('e6000000-0000-0000-0000-000000000020', 'A', 'Osteoporosis', false, 'Ruled out because osteoporosis is a disorder of reduced bone density with normal mineralisation, and does not typically cause abnormal calcium, phosphate, or ALP levels, nor proximal myopathy.', 1),
('e6000000-0000-0000-0000-000000000020', 'B', $x$Paget's disease of bone$x$, false, $x$Ruled out because although Paget's disease raises ALP, it is usually localised, occurs in older patients, and does not cause the systemic biochemical picture of low calcium and phosphate seen here, which points to vitamin D deficiency.$x$, 2),
('e6000000-0000-0000-0000-000000000020', 'C', 'Osteomalacia', true, 'Correct. Diffuse bone pain, proximal myopathy with a waddling gait, low calcium and phosphate, raised alkaline phosphatase, and severe vitamin D deficiency in a patient with reduced sun exposure is the classic presentation of osteomalacia (defective mineralisation of bone due to vitamin D deficiency).', 3),
('e6000000-0000-0000-0000-000000000020', 'D', 'Primary hyperparathyroidism', false, 'Ruled out because primary hyperparathyroidism causes raised (not low) calcium, and the overall biochemical and clinical pattern here (myopathy, low calcium/phosphate, vitamin D deficiency) fits osteomalacia rather than hyperparathyroidism.', 4),
('e6000000-0000-0000-0000-000000000020', 'E', 'Multiple myeloma', false, 'Ruled out because multiple myeloma typically presents with raised (not low) calcium, renal impairment, anaemia, and bone lytic lesions, which is a different pattern from the vitamin D deficiency picture described here.', 5),
('e6000000-0000-0000-0000-000000000021', 'A', 'Osteomalacia', false, 'Ruled out because osteomalacia causes a systemic biochemical picture with low calcium and phosphate, not an isolated raised ALP with otherwise normal biochemistry, and does not produce this focal lytic-sclerotic X-ray pattern.', 1),
('e6000000-0000-0000-0000-000000000021', 'B', 'Primary hyperparathyroidism', false, 'Ruled out because primary hyperparathyroidism causes raised calcium and low phosphate, which are normal in this patient; it does not typically present with this isolated bony ALP rise and focal skeletal X-ray changes.', 2),
('e6000000-0000-0000-0000-000000000021', 'C', 'Metastatic bone disease', false, $x$Ruled out because although metastases can raise ALP, the chronicity, isolated biochemical pattern, skull enlargement, and classic X-ray appearance here are far more consistent with Paget's disease; metastatic disease would not typically present this way without other supporting features.$x$, 3),
('e6000000-0000-0000-0000-000000000021', 'D', 'Multiple myeloma', false, 'Ruled out because myeloma typically causes normal or low ALP (since it is an osteolytic process without accompanying new bone formation), along with anaemia, renal impairment, and hypercalcaemia, none of which are described here.', 4),
('e6000000-0000-0000-0000-000000000021', 'E', $x$Paget's disease of bone$x$, true, $x$Correct. An isolated markedly raised ALP (with normal calcium, phosphate, and liver enzymes, indicating a bony rather than hepatic source), localised bone pain, skull enlargement (increased hat size), and the characteristic mixed lytic-sclerotic 'cotton wool' appearance with cortical thickening on X-ray are classic for Paget's disease of bone, a disorder of abnormally accelerated and disorganised bone remodelling.$x$, 5),
('e6000000-0000-0000-0000-000000000022', 'A', 'Start the bisphosphonate immediately and proceed with dental extraction as planned, with no changes needed', false, 'Ruled out because starting a bisphosphonate before necessary invasive dental work increases the risk of osteonecrosis of the jaw associated with subsequent dental procedures; dental clearance should ideally precede bisphosphonate initiation.', 1),
('e6000000-0000-0000-0000-000000000022', 'B', 'Complete necessary dental treatment, including the extraction, before starting the bisphosphonate', true, 'Correct. Bisphosphonates are associated with a small but serious risk of osteonecrosis of the jaw, particularly after invasive dental procedures. Best practice is to ensure dental health is optimised and any necessary extractions or invasive dental work are completed before starting bisphosphonate therapy, reducing the future need for invasive dental procedures once treatment has begun.', 2),
('e6000000-0000-0000-0000-000000000022', 'C', 'Avoid all future dental treatment indefinitely once bisphosphonate therapy starts', false, 'Ruled out because this is impractical and unnecessary; routine dental care can continue, but planned invasive procedures should ideally be completed before starting treatment or carefully managed with dental input while on treatment, not avoided indefinitely.', 3),
('e6000000-0000-0000-0000-000000000022', 'D', 'Delay osteoporosis treatment for at least 2 years regardless of fracture risk', false, 'Ruled out because this would leave a high fracture-risk patient without treatment for an excessive and clinically inappropriate length of time; the pragmatic approach is to complete necessary dental work first, then start treatment promptly.', 4),
('e6000000-0000-0000-0000-000000000022', 'E', 'Osteonecrosis of the jaw risk is not affected by dental procedures, so timing does not matter', false, 'Ruled out because invasive dental procedures (particularly extractions) performed after starting bisphosphonate therapy are a recognised specific risk factor for osteonecrosis of the jaw, so timing does matter.', 5),
('e6000000-0000-0000-0000-000000000023', 'A', 'Primary hyperparathyroidism', true, $x$Correct. Raised calcium with an inappropriately raised (rather than suppressed) PTH, low phosphate, and the classic 'bones, stones, groans, and moans' symptom complex (bone aches, renal stones, constipation/abdominal symptoms, and psychiatric/cognitive symptoms such as tiredness) is characteristic of primary hyperparathyroidism, most commonly caused by a solitary parathyroid adenoma.$x$, 1),
('e6000000-0000-0000-0000-000000000023', 'B', 'Malignancy-associated hypercalcaemia', false, 'Ruled out because hypercalcaemia of malignancy is typically associated with a suppressed (low), not raised, PTH, as the calcium elevation is PTH-independent (often via PTHrP or bone metastases).', 2),
('e6000000-0000-0000-0000-000000000023', 'C', 'Vitamin D toxicity', false, 'Ruled out because vitamin D toxicity causes hypercalcaemia with a suppressed PTH and typically raised phosphate, not the raised PTH and low phosphate pattern seen here.', 3),
('e6000000-0000-0000-0000-000000000023', 'D', 'Secondary hyperparathyroidism due to chronic kidney disease', false, 'Ruled out because secondary hyperparathyroidism occurs in the context of chronic kidney disease or vitamin D deficiency with typically low or normal calcium (as a compensatory response), and this patient has normal renal function and raised, not low, calcium.', 4),
('e6000000-0000-0000-0000-000000000023', 'E', 'Familial hypocalciuric hypercalcaemia', false, 'Ruled out because although this condition also causes raised calcium with raised or normal PTH, it is rare, usually asymptomatic, and associated with low urinary calcium excretion; the presence of a prior renal stone and symptomatic hypercalcaemia here make primary hyperparathyroidism far more likely.', 5),
('e6000000-0000-0000-0000-000000000024', 'A', 'No specific bone assessment is needed, as osteoporosis only affects postmenopausal women without steroid use', false, 'Ruled out because long-term corticosteroid therapy is itself a major independent risk factor for osteoporosis regardless of menopausal status, and this patient meets criteria warranting proactive bone health assessment.', 1),
('e6000000-0000-0000-0000-000000000024', 'B', 'Stop prednisolone immediately to prevent bone loss', false, 'Ruled out because abruptly stopping long-term corticosteroids is dangerous (risk of adrenal insufficiency) and would also risk a severe flare of her rheumatoid arthritis; steroid doses should only be tapered gradually under specialist guidance, and bone protection should be addressed alongside continued necessary treatment.', 2),
('e6000000-0000-0000-0000-000000000024', 'C', 'Start calcium supplementation alone with no further assessment required', false, 'Ruled out because calcium alone is not sufficient management for a patient at high risk of steroid-induced osteoporosis; formal risk assessment and consideration of bisphosphonate therapy is required.', 3),
('e6000000-0000-0000-0000-000000000024', 'D', 'Assess fracture risk (e.g. using a validated tool such as FRAX) and arrange a DEXA scan, considering bisphosphonate prophylaxis given her long-term steroid use', true, 'Correct. Long-term corticosteroid use (typically defined as prednisolone 7.5 mg/day or more for 3 months or longer) is a major risk factor for osteoporosis and fragility fracture. Current guidance recommends formal fracture risk assessment and DEXA scanning in such patients, with bisphosphonate prophylaxis considered given the ongoing steroid requirement, rather than waiting for a fracture to occur.', 4),
('e6000000-0000-0000-0000-000000000024', 'E', 'Refer for hip replacement surgery as a preventative measure', false, 'Ruled out because there is no indication of joint damage requiring surgery here; the issue is bone density and fracture risk related to long-term steroid use, which is managed medically, not surgically.', 5),
('e6000000-0000-0000-0000-000000000025', 'A', 'Immediate referral for total knee replacement', false, 'Ruled out because joint replacement is reserved for patients with significant functional impairment or pain that has failed to respond to conservative management; it is not first-line for a newly diagnosed, mild-to-moderate presentation.', 1),
('e6000000-0000-0000-0000-000000000025', 'B', 'High-dose oral corticosteroids', false, 'Ruled out because corticosteroids are not indicated for osteoarthritis, which is a degenerative rather than primarily inflammatory process; they carry significant side effects without proven benefit here.', 2),
('e6000000-0000-0000-0000-000000000025', 'C', 'Weight loss advice, exercise/physiotherapy, and simple analgesia (e.g. paracetamol or topical NSAID)', true, 'Correct. This presentation (activity-related pain, brief morning stiffness, crepitus, and X-ray findings of joint space narrowing, osteophytes, and subchondral sclerosis) is classic osteoarthritis. First-line management is conservative: weight loss if overweight, exercise and physiotherapy to strengthen supporting muscles, and simple analgesia, reserving stronger treatments or surgery for those who fail conservative measures.', 3),
('e6000000-0000-0000-0000-000000000025', 'D', 'Methotrexate', false, 'Ruled out because methotrexate is a disease-modifying drug for inflammatory arthritis such as rheumatoid arthritis, not for osteoarthritis, which is not an autoimmune inflammatory condition in the same way.', 4),
('e6000000-0000-0000-0000-000000000025', 'E', 'Strict bed rest until symptoms resolve', false, 'Ruled out because prolonged rest and inactivity worsen outcomes in osteoarthritis by promoting deconditioning and stiffness; staying active and physiotherapy-guided exercise is recommended instead.', 5),
('e6000000-0000-0000-0000-000000000026', 'A', 'Advise staying active, simple analgesia, and safety-net advice, without imaging', true, 'Correct. This is simple mechanical (non-specific) low back pain with no red flag features. Guidelines recommend conservative management: staying active (avoiding prolonged bed rest), simple analgesia (e.g. NSAIDs if not contraindicated), and safety-netting advice about when to seek review, without the need for imaging, which is not indicated in the absence of red flags.', 1),
('e6000000-0000-0000-0000-000000000026', 'B', 'Urgent MRI of the whole spine', false, 'Ruled out because imaging is not indicated for simple mechanical back pain without red flag features; it does not change initial management and exposes the patient to unnecessary investigation.', 2),
('e6000000-0000-0000-0000-000000000026', 'C', 'Strict bed rest for 2 weeks', false, 'Ruled out because prolonged bed rest is not recommended for mechanical back pain and is associated with worse outcomes; patients are encouraged to stay as active as possible.', 3),
('e6000000-0000-0000-0000-000000000026', 'D', 'Immediate referral to spinal surgery', false, 'Ruled out because there are no red flag features (no neurological deficit, no cauda equina symptoms) to warrant urgent surgical referral; this is appropriately managed conservatively in primary care.', 4),
('e6000000-0000-0000-0000-000000000026', 'E', 'High-dose oral corticosteroids', false, 'Ruled out because corticosteroids are not indicated for simple mechanical back pain and would expose the patient to unnecessary risk without proven benefit.', 5),
('e6000000-0000-0000-0000-000000000027', 'A', 'Discharge with oral analgesia and GP follow-up in one week', false, 'Ruled out because this presentation represents a surgical emergency (cauda equina syndrome); discharge without urgent imaging and specialist referral risks permanent neurological damage.', 1),
('e6000000-0000-0000-0000-000000000027', 'B', 'Urgent MRI of the whole spine and immediate referral to spinal surgery', true, 'Correct. Saddle anaesthesia, urinary retention/incomplete emptying, reduced anal tone, and bilateral leg weakness are classic red flags for cauda equina syndrome, a surgical emergency caused by compression of the cauda equina nerve roots (most commonly by a large central disc herniation). This requires immediate MRI to confirm the diagnosis and urgent spinal surgical referral for decompression, as delay risks permanent bladder, bowel, and lower limb dysfunction.', 2),
('e6000000-0000-0000-0000-000000000027', 'C', 'Physiotherapy referral for core strengthening exercises', false, 'Ruled out because physiotherapy is entirely inappropriate for a suspected cauda equina syndrome, which requires emergency imaging and surgical assessment, not exercise therapy.', 3),
('e6000000-0000-0000-0000-000000000027', 'D', 'Reassure and advise to stay active as this is likely simple mechanical back pain', false, 'Ruled out because the presence of saddle anaesthesia, urinary symptoms, and bilateral lower limb weakness are red flags that clearly distinguish this from simple mechanical back pain, and demand emergency action.', 4),
('e6000000-0000-0000-0000-000000000027', 'E', 'Arrange outpatient lumbar spine X-ray', false, 'Ruled out because plain X-ray does not visualise the soft tissue/disc/nerve root detail needed to diagnose cauda equina syndrome, and outpatient (non-urgent) imaging is far too slow for a time-critical surgical emergency.', 5),
('e6000000-0000-0000-0000-000000000028', 'A', 'Reassure and manage as simple mechanical back pain with analgesia only', false, 'Ruled out because the combination of a history of malignancy, unexplained weight loss, and night sweats are red flag features that must be urgently investigated, not managed as simple mechanical back pain.', 1),
('e6000000-0000-0000-0000-000000000028', 'B', 'Refer for physiotherapy and review in 6 weeks', false, 'Ruled out because red flag features indicating possible malignant spinal disease require urgent imaging now, not a delayed physiotherapy-based approach that could allow progression to spinal cord compression.', 2),
('e6000000-0000-0000-0000-000000000028', 'C', 'Arrange outpatient rheumatology referral for suspected inflammatory back pain', false, 'Ruled out because the clinical picture (older patient, prior malignancy, weight loss, night sweats) is far more suggestive of possible metastatic disease than of an inflammatory spondyloarthropathy, which typically presents in younger patients with morning stiffness improving with exercise.', 3),
('e6000000-0000-0000-0000-000000000028', 'D', 'Start empirical broad-spectrum antibiotics for presumed discitis without further investigation', false, 'Ruled out because although infection is a differential to consider, starting antibiotics without imaging or microbiological confirmation is inappropriate; urgent imaging is needed first to establish the diagnosis and guide targeted treatment.', 4),
('e6000000-0000-0000-0000-000000000028', 'E', 'Urgent MRI spine to investigate for possible spinal metastasis', true, 'Correct. Back pain with red flag features of unexplained weight loss, night sweats, and a history of previous malignancy (prostate cancer, which commonly metastasises to bone) raises significant concern for spinal metastatic disease, even in the absence of neurological deficit at presentation. This requires urgent MRI imaging to assess for metastatic spinal cord compression risk and guide oncological management, rather than conservative management as for simple mechanical back pain.', 5),
('e6000000-0000-0000-0000-000000000029', 'A', 'Intra-articular hip corticosteroid injection as definitive long-term treatment', false, 'Ruled out because intra-articular steroid injections provide only temporary symptomatic relief and are not a definitive long-term solution for advanced, refractory hip osteoarthritis with major functional limitation; surgical referral is more appropriate at this stage.', 1),
('e6000000-0000-0000-0000-000000000029', 'B', 'Continue current conservative management unchanged, as surgery is never appropriate for osteoarthritis', false, 'Ruled out because joint replacement surgery is an established and highly effective treatment for osteoarthritis that has failed conservative management, and continuing an already-ineffective approach is not appropriate.', 2),
('e6000000-0000-0000-0000-000000000029', 'C', 'Start high-dose oral corticosteroids', false, 'Ruled out because corticosteroids are not an appropriate or effective treatment for osteoarthritis and carry significant side-effect risk without addressing the underlying joint damage.', 3),
('e6000000-0000-0000-0000-000000000029', 'D', 'Referral for consideration of total hip replacement', true, 'Correct. This patient has osteoarthritis of the hip with significant functional impairment that has failed to respond to appropriate conservative management (analgesia and physiotherapy) over a reasonable period. Referral for consideration of total hip replacement is the appropriate next step, as joint replacement provides substantial pain relief and functional improvement in this scenario.', 4),
('e6000000-0000-0000-0000-000000000029', 'E', 'Refer for below-knee amputation', false, 'Ruled out because this is an entirely disproportionate and incorrect intervention for hip osteoarthritis; it is not indicated here at all.', 5),
('e6000000-0000-0000-0000-000000000030', 'A', 'Peripheral arterial disease causing vascular claudication', false, 'Ruled out because vascular claudication is typically relieved simply by stopping and standing still (rest relieves the ischaemic pain regardless of posture), and a normal ankle-brachial pressure index of 1.1 argues against significant peripheral arterial disease.', 1),
('e6000000-0000-0000-0000-000000000030', 'B', 'Cauda equina syndrome', false, 'Ruled out because there is no saddle anaesthesia, bladder/bowel dysfunction, or acute severe presentation described here; this is a chronic, positional, exertional pattern of pain consistent with claudication rather than an acute cauda equina emergency.', 2),
('e6000000-0000-0000-0000-000000000030', 'C', 'Lumbar spinal stenosis causing neurogenic claudication', true, 'Correct. Neurogenic claudication from lumbar spinal stenosis characteristically causes bilateral buttock/leg pain on walking that is relieved by sitting or leaning forward (flexion increases spinal canal diameter), rather than simply by stopping while standing, which distinguishes it from vascular claudication. Normal peripheral pulses and a normal ankle-brachial pressure index further support a neurogenic rather than vascular cause.', 3),
('e6000000-0000-0000-0000-000000000030', 'D', 'Deep vein thrombosis', false, 'Ruled out because DVT typically causes unilateral leg swelling, pain, and warmth that is not specifically related to walking distance and relieved by posture change, which does not match this exertional, posture-dependent bilateral pattern.', 4),
('e6000000-0000-0000-0000-000000000030', 'E', 'Meralgia paraesthetica', false, 'Ruled out because meralgia paraesthetica causes localised numbness/burning over the lateral thigh from lateral cutaneous nerve entrapment, not bilateral exertional buttock and leg pain relieved by spinal flexion.', 5),
('e6000000-0000-0000-0000-000000000031', 'A', 'Mechanical low back pain', false, 'Ruled out because mechanical back pain is typically worse with activity and better with rest, the opposite pattern to this presentation, and would not be associated with raised inflammatory markers, HLA-B27 positivity, or sacroiliac X-ray changes.', 1),
('e6000000-0000-0000-0000-000000000031', 'B', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis characteristically affects small peripheral joints symmetrically and is not the classic cause of inflammatory axial back pain with sacroiliitis; it is also not associated with HLA-B27.', 2),
('e6000000-0000-0000-0000-000000000031', 'C', 'Osteoarthritis of the lumbar spine', false, 'Ruled out because osteoarthritis causes mechanical, activity-worsened pain in older patients, not inflammatory pain improving with exercise in a young man with raised inflammatory markers and sacroiliitis.', 3),
('e6000000-0000-0000-0000-000000000031', 'D', 'Ankylosing spondylitis', true, 'Correct. Inflammatory back pain in a young man (age of onset typically under 45), with morning stiffness lasting over an hour, improvement with exercise but not rest, raised inflammatory markers, HLA-B27 positivity, and bilateral sacroiliitis on X-ray is the classic presentation of ankylosing spondylitis, a seronegative spondyloarthropathy.', 4),
('e6000000-0000-0000-0000-000000000031', 'E', 'Multiple myeloma', false, 'Ruled out because myeloma typically presents in older patients with bone pain, anaemia, renal impairment, and hypercalcaemia, not this classic pattern of young-onset inflammatory axial back pain with HLA-B27 and sacroiliitis.', 5),
('e6000000-0000-0000-0000-000000000032', 'A', 'Dactylitis, associated with psoriatic arthritis', true, $x$Correct. Diffuse swelling of an entire digit ('sausage finger'), termed dactylitis, results from combined synovitis and tenosynovitis and is a characteristic feature of psoriatic arthritis, particularly in a patient with known psoriasis and nail changes such as pitting.$x$, 1),
('e6000000-0000-0000-0000-000000000032', 'B', $x$Heberden's node, associated with osteoarthritis$x$, false, $x$Ruled out because Heberden's nodes are bony swellings at the distal interphalangeal joints seen in osteoarthritis, not diffuse whole-digit swelling, and are not linked to psoriasis or nail pitting.$x$, 2),
('e6000000-0000-0000-0000-000000000032', 'C', 'Boutonniere deformity, associated with rheumatoid arthritis', false, 'Ruled out because Boutonniere deformity is a specific finger deformity (flexion at the PIP joint with hyperextension at the DIP joint) seen in rheumatoid arthritis, not diffuse digit swelling, and does not fit this description.', 3),
('e6000000-0000-0000-0000-000000000032', 'D', 'Tophus, associated with chronic gout', false, 'Ruled out because a tophus is a subcutaneous deposit of urate crystals causing a firm nodule, not diffuse swelling of the entire digit, and is unrelated to psoriasis.', 4),
('e6000000-0000-0000-0000-000000000032', 'E', $x$Raynaud's phenomenon, associated with systemic sclerosis$x$, false, $x$Ruled out because Raynaud's phenomenon describes episodic colour change (white-blue-red) triggered by cold, not diffuse persistent digit swelling, and is unrelated to this presentation.$x$, 5),
('e6000000-0000-0000-0000-000000000033', 'A', 'Septic arthritis', false, 'Ruled out because septic arthritis is a direct joint infection typically presenting with a single hot, severely painful joint and systemic sepsis, not this post-infective triad of arthritis, conjunctivitis, and sterile urethritis affecting multiple sites.', 1),
('e6000000-0000-0000-0000-000000000033', 'B', 'Reactive arthritis', true, $x$Correct. This triad of asymmetrical oligoarthritis, conjunctivitis, and urethritis/dysuria (with sterile urine) occurring 1-4 weeks after a gastrointestinal (or genitourinary) infection is classic for reactive arthritis, historically remembered by the triad 'can't see, can't pee, can't climb a tree.' Campylobacter, Salmonella, Shigella, and Chlamydia are recognised triggering organisms.$x$, 2),
('e6000000-0000-0000-0000-000000000033', 'C', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis presents as a symmetrical small-joint polyarthritis with a chronic course, not an acute asymmetrical oligoarthritis with conjunctivitis and urethritis following an infection.', 3),
('e6000000-0000-0000-0000-000000000033', 'D', 'Gonococcal arthritis', false, 'Ruled out because although gonococcal infection can cause a septic or reactive arthritis, this patient denies new sexual partners and the clinical triad described (post-diarrhoeal illness, conjunctivitis, arthritis, sterile urethritis) is classic for reactive arthritis rather than active gonococcal joint infection.', 4),
('e6000000-0000-0000-0000-000000000033', 'E', 'Systemic lupus erythematosus', false, 'Ruled out because this acute post-infective triad of joint, eye, and urinary tract symptoms is not typical of SLE, which usually presents with a broader multisystem picture including rash, serositis, and characteristic autoantibodies.', 5),
('e6000000-0000-0000-0000-000000000034', 'A', 'Coincidental new-onset rheumatoid arthritis', false, 'Ruled out because the temporal relationship between joint symptoms and IBD flare activity, with improvement as bowel symptoms settle, points to enteropathic arthritis rather than an unrelated new diagnosis of rheumatoid arthritis.', 1),
('e6000000-0000-0000-0000-000000000034', 'B', 'Septic arthritis secondary to bowel bacteraemia', false, 'Ruled out because there is no mention of fever, systemic sepsis, or a single acutely hot joint; the pattern of two joints fluctuating with bowel disease activity fits enteropathic arthritis, not septic arthritis.', 2),
('e6000000-0000-0000-0000-000000000034', 'C', $x$Enteropathic arthritis associated with her Crohn's disease$x$, true, 'Correct. Peripheral arthritis occurring in association with inflammatory bowel disease, whose activity often parallels bowel disease activity (improving as the bowel flare settles), is termed enteropathic arthritis, a recognised seronegative spondyloarthropathy associated with IBD.', 3),
('e6000000-0000-0000-0000-000000000034', 'D', 'Gout secondary to mesalazine therapy', false, 'Ruled out because mesalazine is not a recognised cause of gout, and this presentation does not describe the classic acute monoarthritis of gout.', 4),
('e6000000-0000-0000-0000-000000000034', 'E', 'Drug-induced lupus from mesalazine', false, 'Ruled out because mesalazine is not a classic cause of drug-induced lupus (unlike hydralazine or procainamide), and there are no other lupus-like features described here.', 5),
('e6000000-0000-0000-0000-000000000035', 'A', 'Reassure and advise use of over-the-counter lubricating eye drops', false, 'Ruled out because this presentation is concerning for acute anterior uveitis, which requires urgent specialist assessment and treatment (typically topical steroids and mydriatics), not simple lubrication, given the risk of sight-threatening complications.', 1),
('e6000000-0000-0000-0000-000000000035', 'B', 'Start oral antibiotics for presumed bacterial conjunctivitis', false, 'Ruled out because bacterial conjunctivitis typically causes purulent discharge without significant pain, photophobia, or pupillary abnormality; this presentation with ciliary injection and an irregular pupil is not consistent with simple conjunctivitis.', 2),
('e6000000-0000-0000-0000-000000000035', 'C', 'Arrange routine ophthalmology outpatient review in 6 weeks', false, 'Ruled out because acute anterior uveitis is an ophthalmological emergency requiring same-day assessment and treatment; a 6-week delay risks serious complications including permanent visual impairment.', 3),
('e6000000-0000-0000-0000-000000000035', 'D', 'Patch the eye and review in 48 hours', false, 'Ruled out because eye patching is not appropriate management for suspected uveitis and delays the urgent specialist assessment and treatment (topical corticosteroids, cycloplegics) that this condition requires.', 4),
('e6000000-0000-0000-0000-000000000035', 'E', 'Same-day referral to ophthalmology for assessment of suspected acute anterior uveitis', true, 'Correct. Painful red eye with photophobia, blurred vision, ciliary injection, and an irregular pupil in a patient with ankylosing spondylitis is highly suggestive of acute anterior uveitis, a recognised extra-articular manifestation of spondyloarthropathy. This requires same-day ophthalmology assessment, as delayed treatment risks complications including glaucoma and permanent visual loss.', 5),
('e6000000-0000-0000-0000-000000000036', 'A', 'Psoriatic arthritis', true, $x$Correct. This is the classic 'pencil-in-cup' deformity seen on X-ray in psoriatic arthritis, resulting from severe erosive change at the distal interphalangeal joints, sometimes progressing to arthritis mutilans. This finding, combined with a background of psoriasis, strongly supports the diagnosis.$x$, 1),
('e6000000-0000-0000-0000-000000000036', 'B', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis characteristically spares the DIP joints and causes different radiographic changes (periarticular erosions, juxta-articular osteopenia at MCP/PIP joints), not the pencil-in-cup deformity described here.', 2),
('e6000000-0000-0000-0000-000000000036', 'C', 'Osteoarthritis', false, $x$Ruled out because osteoarthritis causes joint space narrowing with osteophytes and subchondral sclerosis (and Heberden's nodes at the DIP joints clinically), not the erosive pencil-in-cup appearance characteristic of psoriatic arthritis.$x$, 3),
('e6000000-0000-0000-0000-000000000036', 'D', 'Gout', false, $x$Ruled out because although gout can cause erosive changes and 'punched-out' lytic lesions with overhanging edges, it does not classically produce the specific pencil-in-cup deformity, and there is no mention of tophi or the typical acute presentation of gout.$x$, 4),
('e6000000-0000-0000-0000-000000000036', 'E', 'Septic arthritis', false, 'Ruled out because septic arthritis is an acute infective process, not a cause of chronic erosive radiographic deformity such as pencil-in-cup changes.', 5),
('e6000000-0000-0000-0000-000000000037', 'A', 'Adhesive capsulitis (frozen shoulder)', false, 'Ruled out because frozen shoulder causes globally restricted active and passive range of movement in all directions, not an isolated painful arc with normal passive movement as described here.', 1),
('e6000000-0000-0000-0000-000000000037', 'B', 'Acromioclavicular joint osteoarthritis', false, 'Ruled out because ACJ osteoarthritis typically causes localised pain at the top of the shoulder, worse with cross-body adduction, rather than the classic mid-range painful arc on abduction described here.', 2),
('e6000000-0000-0000-0000-000000000037', 'C', 'Glenohumeral joint dislocation', false, 'Ruled out because there is no history of trauma or acute instability event, and dislocation would present acutely with visible deformity and inability to move the joint, not a chronic overuse pattern.', 3),
('e6000000-0000-0000-0000-000000000037', 'D', 'Subacromial impingement syndrome (rotator cuff tendinopathy)', true, $x$Correct. Pain reproduced specifically within a 'painful arc' of abduction (typically 60-120 degrees), in the context of repetitive overhead activity (occupational overuse), with normal passive range of movement, is classic for subacromial impingement syndrome due to rotator cuff tendinopathy/subacromial bursitis.$x$, 4),
('e6000000-0000-0000-0000-000000000037', 'E', 'Polymyalgia rheumatica', false, 'Ruled out because PMR classically causes bilateral shoulder and hip girdle pain and stiffness with raised inflammatory markers in an older patient, not a unilateral mechanical painful arc related to occupational overuse.', 5),
('e6000000-0000-0000-0000-000000000038', 'A', 'Subacromial impingement syndrome', false, 'Ruled out because impingement causes a painful arc with preserved passive range of movement, not the global restriction of both active and passive movement seen in this patient.', 1),
('e6000000-0000-0000-0000-000000000038', 'B', 'Rotator cuff tear', false, 'Ruled out because a rotator cuff tear typically causes weakness on specific resisted movements (e.g. positive drop-arm test) with preserved passive range of movement, rather than global restriction of passive movement in all directions.', 2),
('e6000000-0000-0000-0000-000000000038', 'C', 'Adhesive capsulitis (frozen shoulder)', true, 'Correct. Global restriction of both active and passive shoulder movement in all planes, developing over months, with a normal X-ray, in a patient with diabetes (a recognised risk factor), is classic for adhesive capsulitis (frozen shoulder), which typically progresses through painful, stiffening, and thawing phases.', 3),
('e6000000-0000-0000-0000-000000000038', 'D', 'Glenohumeral osteoarthritis', false, 'Ruled out because osteoarthritis would typically show degenerative changes on X-ray (joint space narrowing, osteophytes), which is not present here (normal X-ray), making frozen shoulder more likely.', 4),
('e6000000-0000-0000-0000-000000000038', 'E', 'Cervical radiculopathy', false, 'Ruled out because radiculopathy causes pain radiating in a dermatomal distribution with possible neurological signs, not global restriction of shoulder movement in all directions with a normal X-ray.', 5),
('e6000000-0000-0000-0000-000000000039', 'A', $x$Medial epicondylitis (golfer's elbow)$x$, false, 'Ruled out because medial epicondylitis causes pain over the medial epicondyle reproduced by resisted wrist flexion, not the lateral-sided pain with resisted extension described here.', 1),
('e6000000-0000-0000-0000-000000000039', 'B', 'Olecranon bursitis', false, 'Ruled out because olecranon bursitis presents with a fluctuant swelling over the posterior point of the elbow (olecranon), not lateral epicondylar tenderness with pain on resisted wrist extension.', 2),
('e6000000-0000-0000-0000-000000000039', 'C', 'Cubital tunnel syndrome', false, 'Ruled out because cubital tunnel syndrome (ulnar nerve entrapment at the elbow) causes numbness/tingling in the ring and little fingers, not isolated lateral epicondylar tenderness reproduced by resisted wrist extension.', 3),
('e6000000-0000-0000-0000-000000000039', 'D', 'Rheumatoid arthritis of the elbow', false, 'Ruled out because rheumatoid arthritis typically causes symmetrical joint swelling and synovitis rather than an isolated overuse tendinopathy localised to the lateral epicondyle.', 4),
('e6000000-0000-0000-0000-000000000039', 'E', 'Lateral epicondylitis (tennis elbow)', true, 'Correct. Lateral elbow pain worse with gripping and resisted wrist extension, tender over the lateral epicondyle, in someone with repetitive overuse activity (tennis, or repetitive gripping/manual work) is classic for lateral epicondylitis, an overuse tendinopathy of the common extensor origin.', 5),
('e6000000-0000-0000-0000-000000000040', 'A', 'Achilles tendinopathy', false, 'Ruled out because Achilles tendinopathy causes pain and tenderness along the posterior aspect of the ankle/heel at the Achilles tendon, not under the heel at the medial calcaneal insertion described here.', 1),
('e6000000-0000-0000-0000-000000000040', 'B', 'Plantar fasciitis', true, 'Correct. Heel pain that is worst with the first steps in the morning or after rest, easing somewhat with activity, and tender at the medial calcaneal insertion of the plantar fascia, is the classic presentation of plantar fasciitis, common in runners and associated with repetitive loading of the foot.', 2),
('e6000000-0000-0000-0000-000000000040', 'C', 'Calcaneal stress fracture', false, 'Ruled out because while possible in runners, a stress fracture typically causes more constant, activity-related pain that worsens rather than eases with continued walking, and usually shows diffuse rather than focal medial tenderness; this presentation fits plantar fasciitis better.', 3),
('e6000000-0000-0000-0000-000000000040', 'D', 'Gout', false, 'Ruled out because gout typically causes acute, hot, swollen joint inflammation (classically the first MTP joint), not chronic activity-related heel tenderness without swelling or redness.', 4),
('e6000000-0000-0000-0000-000000000040', 'E', 'Tarsal tunnel syndrome', false, 'Ruled out because tarsal tunnel syndrome causes numbness/tingling in the sole of the foot from posterior tibial nerve entrapment, not localised mechanical tenderness at the calcaneal insertion of the plantar fascia.', 5),
('e6000000-0000-0000-0000-000000000041', 'A', 'Carpal tunnel syndrome', false, 'Ruled out because carpal tunnel syndrome causes numbness and tingling in the median nerve distribution (thumb, index, middle, and half of the ring finger), typically worse at night, not sharp radial wrist pain reproduced by the Finkelstein test.', 1),
('e6000000-0000-0000-0000-000000000041', 'B', 'Scaphoid fracture', false, 'Ruled out because there is no history of trauma or fall onto an outstretched hand, and the pain is reproduced by a specific tendon-provocation test rather than direct bony tenderness in the anatomical snuffbox consistent with a fracture.', 2),
('e6000000-0000-0000-0000-000000000041', 'C', 'Trigger finger', false, 'Ruled out because trigger finger causes catching/locking of a finger during flexion/extension due to flexor tendon pathology, not radial-sided wrist pain reproduced by thumb/wrist positioning.', 3),
('e6000000-0000-0000-0000-000000000041', 'D', 'Rheumatoid arthritis of the wrist', false, 'Ruled out because this is a localised overuse tenosynovitis with a specific positive provocation test, not the symmetrical inflammatory polyarthritis pattern expected in rheumatoid arthritis.', 4),
('e6000000-0000-0000-0000-000000000041', 'E', $x$De Quervain's tenosynovitis$x$, true, $x$Correct. Radial-sided wrist pain reproduced by the Finkelstein test (thumb tucked into a fist with ulnar deviation of the wrist) is diagnostic of de Quervain's tenosynovitis, inflammation of the tendons of the first dorsal compartment (abductor pollicis longus and extensor pollicis brevis). It is common in new mothers due to repetitive lifting of infants with the thumb in an abducted/extended position.$x$, 5),
('e6000000-0000-0000-0000-000000000042', 'A', 'Complete Achilles tendon rupture', true, $x$Correct. A sudden sharp pain with an audible 'pop' during sporting activity, a palpable gap in the tendon, weakness of plantarflexion, and a positive Simmonds (calf squeeze) test (absent plantarflexion on calf squeeze) are all classic findings of complete Achilles tendon rupture. This requires urgent orthopaedic assessment for consideration of surgical or conservative (cast/brace) management.$x$, 1),
('e6000000-0000-0000-0000-000000000042', 'B', 'Achilles tendinopathy', false, 'Ruled out because tendinopathy is a chronic overuse condition causing gradual pain, not a sudden acute rupture event with an audible pop, palpable gap, and positive Simmonds test.', 2),
('e6000000-0000-0000-0000-000000000042', 'C', 'Gastrocnemius muscle strain', false, 'Ruled out because although this can also cause sudden calf pain during sport, it would not typically produce a palpable gap in the Achilles tendon itself or a positive Simmonds test, which specifically indicates tendon discontinuity.', 3),
('e6000000-0000-0000-0000-000000000042', 'D', 'Ankle sprain (lateral ligament injury)', false, 'Ruled out because this presentation localises to the Achilles tendon (posterior calf/heel) with a palpable gap and abnormal calf squeeze test, not to the lateral ankle ligaments.', 4),
('e6000000-0000-0000-0000-000000000042', 'E', 'Deep vein thrombosis', false, 'Ruled out because DVT typically causes gradual calf swelling and pain rather than a sudden pop during exertion with a palpable tendon gap and abnormal Simmonds test.', 5),
('e6000000-0000-0000-0000-000000000043', 'A', 'Cubital tunnel syndrome', false, 'Ruled out because cubital tunnel syndrome (ulnar nerve entrapment at the elbow) causes numbness/tingling in the ring and little fingers, not the thumb, index, and middle finger distribution described here.', 1),
('e6000000-0000-0000-0000-000000000043', 'B', $x$De Quervain's tenosynovitis$x$, false, $x$Ruled out because de Quervain's causes localised radial wrist pain reproduced by the Finkelstein test, not nocturnal numbness/tingling in a median nerve distribution.$x$, 2),
('e6000000-0000-0000-0000-000000000043', 'C', 'Carpal tunnel syndrome', true, $x$Correct. Nocturnal numbness and tingling affecting the thumb, index, and middle fingers (median nerve distribution), relieved by shaking the hand, with a positive Tinel's sign (tapping over the wrist) and Phalen's test (sustained wrist flexion), is classic for carpal tunnel syndrome. Pregnancy (due to fluid retention) is a well-recognised risk factor, and symptoms often improve after delivery.$x$, 3),
('e6000000-0000-0000-0000-000000000043', 'D', 'Cervical radiculopathy (C6 nerve root)', false, $x$Ruled out because although C6 radiculopathy can cause thumb/index finger symptoms, the specific reproduction of symptoms with Tinel's and Phalen's tests at the wrist, combined with the classic pregnancy association, points to carpal tunnel syndrome rather than a cervical spine cause.$x$, 4),
('e6000000-0000-0000-0000-000000000043', 'E', $x$Raynaud's phenomenon$x$, false, $x$Ruled out because Raynaud's causes episodic colour change (white-blue-red) triggered by cold, not persistent nocturnal numbness/tingling reproduced by specific wrist provocation tests.$x$, 5),
('e6000000-0000-0000-0000-000000000044', 'A', 'Arrange temporal artery biopsy and withhold steroids until results are available', false, 'Ruled out because waiting for biopsy results before starting steroids risks sudden, irreversible visual loss; treatment should begin immediately on clinical suspicion, with biopsy performed as soon as possible afterward (ideally within 1 week) to confirm the diagnosis, but not delaying treatment.', 1),
('e6000000-0000-0000-0000-000000000044', 'B', 'Start high-dose oral corticosteroids immediately, without waiting for temporal artery biopsy results', true, 'Correct. This presentation (new temporal headache, scalp tenderness, jaw claudication, raised ESR/CRP, abnormal temporal artery) is classic for giant cell arteritis (temporal arteritis). This is a medical emergency due to the risk of sudden irreversible visual loss from ophthalmic artery involvement. High-dose corticosteroids (typically prednisolone 40-60mg daily) should be started immediately on clinical suspicion, without waiting for temporal artery biopsy or specialist review, to prevent this complication.', 2),
('e6000000-0000-0000-0000-000000000044', 'C', 'Simple analgesia and reassurance, with review in 2 weeks', false, 'Ruled out because this delay risks permanent visual loss from untreated giant cell arteritis; this presentation requires immediate treatment, not deferred review.', 3),
('e6000000-0000-0000-0000-000000000044', 'D', 'Start low-dose aspirin alone as the primary treatment', false, 'Ruled out because aspirin alone does not adequately treat the underlying vasculitic inflammation of giant cell arteritis and does not protect against visual loss in the way that urgent high-dose corticosteroids do.', 4),
('e6000000-0000-0000-0000-000000000044', 'E', 'Refer routinely to rheumatology outpatient clinic for assessment in 4-6 weeks', false, 'Ruled out because giant cell arteritis is a medical emergency requiring same-day treatment initiation, not a routine, delayed outpatient referral.', 5),
('e6000000-0000-0000-0000-000000000045', 'A', 'Increase the oral prednisolone dose slightly and review in clinic in one week', false, 'Ruled out because sudden visual loss in the context of GCA is a same-day emergency requiring urgent escalation to intravenous steroids and emergency ophthalmology review, not a small oral dose increase with delayed follow-up.', 1),
('e6000000-0000-0000-0000-000000000045', 'B', 'Reassure the patient that this is an expected side effect of prednisolone and no action is needed', false, 'Ruled out because visual loss in a patient with GCA is not an expected steroid side effect; it indicates active disease causing ischaemic optic neuropathy and requires emergency treatment to protect remaining vision.', 2),
('e6000000-0000-0000-0000-000000000045', 'C', 'Stop prednisolone as it may be causing the visual symptoms', false, 'Ruled out because stopping steroids in active GCA with visual involvement would be dangerous, allowing further progression of arteritic ischaemia and risking complete, bilateral, irreversible visual loss.', 3),
('e6000000-0000-0000-0000-000000000045', 'D', 'Immediate same-day ophthalmology referral and urgent administration of intravenous methylprednisolone', true, 'Correct. Sudden visual loss (or amaurosis fugax, as described the previous day) in a patient with giant cell arteritis, even while already on oral steroids, represents impending or actual ischaemic optic neuropathy and is a same-day ophthalmological and rheumatological emergency. Urgent intravenous methylprednisolone (pulsed high-dose) should be given without delay alongside emergency ophthalmology assessment, as the fellow eye remains at risk and any visual loss that has already occurred may be irreversible if treatment is further delayed.', 4),
('e6000000-0000-0000-0000-000000000045', 'E', 'Arrange outpatient MRI brain in 2 weeks', false, 'Ruled out because this represents a vision-threatening emergency requiring immediate treatment and same-day specialist assessment, not delayed outpatient imaging.', 5),
('e6000000-0000-0000-0000-000000000046', 'A', 'Polymyalgia rheumatica', true, 'Correct. Bilateral shoulder and hip girdle pain and stiffness (worse in the morning, lasting over an hour) in a patient over 50, with systemic symptoms (fatigue, weight loss) and markedly raised inflammatory markers, but no true muscle weakness or raised CK, is classic for polymyalgia rheumatica. PMR shows a dramatic response to low-dose corticosteroids, which can also support the diagnosis.', 1),
('e6000000-0000-0000-0000-000000000046', 'B', 'Polymyositis', false, 'Ruled out because polymyositis causes true proximal muscle weakness with a raised creatine kinase, neither of which is present here; PMR causes pain and stiffness without objective weakness or CK elevation.', 2),
('e6000000-0000-0000-0000-000000000046', 'C', 'Fibromyalgia', false, 'Ruled out because fibromyalgia typically causes widespread chronic pain without raised inflammatory markers, whereas this patient has a markedly raised ESR and CRP, which points to an inflammatory process such as PMR.', 3),
('e6000000-0000-0000-0000-000000000046', 'D', 'Rheumatoid arthritis', false, 'Ruled out because rheumatoid arthritis characteristically causes symmetrical small-joint synovitis (hands, wrists, feet), not the girdle (shoulder/hip) pattern of pain and stiffness described here.', 4),
('e6000000-0000-0000-0000-000000000046', 'E', 'Osteoarthritis of the shoulders and hips', false, 'Ruled out because osteoarthritis is a mechanical, activity-related condition without associated systemic symptoms or markedly raised inflammatory markers, unlike this presentation.', 5),
('e6000000-0000-0000-0000-000000000047', 'A', 'Giant cell arteritis', false, 'Ruled out because giant cell arteritis typically affects patients over 50 and involves cranial and other medium-to-large vessels (particularly temporal arteries), not the young-onset subclavian/aortic arch pattern with absent pulses described here.', 1),
('e6000000-0000-0000-0000-000000000047', 'B', 'Takayasu arteritis', true, 'Correct. Takayasu arteritis is a large-vessel vasculitis affecting the aorta and its major branches, typically presenting in young women (under 40) with limb claudication, asymmetrical or absent pulses, differential blood pressures between limbs, bruits over affected vessels, and raised inflammatory markers.', 2),
('e6000000-0000-0000-0000-000000000047', 'C', 'Peripheral arterial disease due to atherosclerosis', false, 'Ruled out because atherosclerotic peripheral arterial disease is uncommon in a healthy 26-year-old woman without risk factors, and does not typically present with raised inflammatory markers; the pattern here is more consistent with a large-vessel vasculitis.', 3),
('e6000000-0000-0000-0000-000000000047', 'D', 'Thoracic outlet syndrome', false, 'Ruled out because thoracic outlet syndrome causes positional compression symptoms from neurovascular structures at the thoracic outlet, but would not typically cause raised inflammatory markers or the vessel-specific bruit described here.', 4),
('e6000000-0000-0000-0000-000000000047', 'E', 'Kawasaki disease', false, 'Ruled out because Kawasaki disease is a medium-vessel vasculitis occurring in young children, not adult women, and presents with fever, rash, and mucocutaneous changes rather than this chronic large-vessel pattern.', 5),
('e6000000-0000-0000-0000-000000000048', 'A', 'Microscopic polyangiitis', false, 'Ruled out because although microscopic polyangiitis is also ANCA-associated and causes renal and pulmonary disease, it typically lacks the granulomatous upper respiratory tract features (chronic sinusitis, saddle nose deformity) and is more often associated with perinuclear ANCA (pANCA)/anti-MPO rather than cANCA/PR3.', 1),
('e6000000-0000-0000-0000-000000000048', 'B', 'Goodpasture syndrome (anti-GBM disease)', false, 'Ruled out because Goodpasture syndrome causes pulmonary haemorrhage and glomerulonephritis via anti-glomerular basement membrane antibodies, not ANCA, and does not classically cause chronic sinusitis or saddle nose deformity.', 2),
('e6000000-0000-0000-0000-000000000048', 'C', 'Eosinophilic granulomatosis with polyangiitis (Churg-Strauss syndrome)', false, 'Ruled out because this condition is characterised by asthma, eosinophilia, and vasculitis, typically with pANCA positivity, not the cANCA/PR3-positive picture with saddle nose deformity described here.', 3),
('e6000000-0000-0000-0000-000000000048', 'D', 'IgA nephropathy', false, 'Ruled out because IgA nephropathy typically causes isolated renal disease (often with episodic macroscopic haematuria after upper respiratory infection) without the systemic granulomatous upper/lower respiratory features or ANCA positivity described in this vignette.', 4),
('e6000000-0000-0000-0000-000000000048', 'E', $x$Granulomatosis with polyangiitis (formerly Wegener's granulomatosis)$x$, true, 'Correct. The combination of upper respiratory tract involvement (chronic sinusitis, saddle nose deformity from nasal cartilage destruction), lower respiratory tract involvement (haemoptysis), and renal involvement (rapidly progressive glomerulonephritis with haematuria, proteinuria, and rising creatinine), with positive cANCA/anti-PR3 antibodies, is classic for granulomatosis with polyangiitis, an ANCA-associated small-vessel vasculitis.', 5),
('e6000000-0000-0000-0000-000000000049', 'A', 'Meningococcal septicaemia', false, 'Ruled out because meningococcal septicaemia causes a rapidly progressive purpuric/petechial rash with fever and signs of sepsis/shock, which is absent here; this child is well, afebrile, and has the classic distribution and associated features of HSP rather than sepsis.', 1),
('e6000000-0000-0000-0000-000000000049', 'B', 'Immune thrombocytopenic purpura (ITP)', false, 'Ruled out because ITP causes petechiae and bruising due to low platelet count, without the abdominal pain, arthritis, or renal involvement described here, and platelet count is typically low (not mentioned as abnormal in this vignette, and the clinical pattern is otherwise classic for HSP).', 2),
('e6000000-0000-0000-0000-000000000049', 'C', 'Kawasaki disease', false, 'Ruled out because Kawasaki disease presents with prolonged fever, conjunctivitis, mucosal changes, rash, and lymphadenopathy, not this classic tetrad of palpable purpura, abdominal pain, arthritis, and renal involvement.', 3),
('e6000000-0000-0000-0000-000000000049', 'D', 'Henoch-Schonlein purpura (IgA vasculitis)', true, 'Correct. This tetrad of palpable purpuric rash (typically over the buttocks and extensor surfaces of the legs), abdominal pain, arthritis/arthralgia, and renal involvement (haematuria/proteinuria), often following an upper respiratory tract infection in a child, is classic for Henoch-Schonlein purpura (now called IgA vasculitis), a small-vessel vasculitis mediated by IgA immune complex deposition.', 4),
('e6000000-0000-0000-0000-000000000049', 'E', 'Haemolytic uraemic syndrome', false, 'Ruled out because haemolytic uraemic syndrome presents with haemolytic anaemia, thrombocytopenia, and acute kidney injury (often after diarrhoeal illness with E. coli O157), not a palpable purpuric rash with arthritis as the presenting feature.', 5),
('e6000000-0000-0000-0000-000000000050', 'A', 'Herpes simplex virus infection', false, $x$Ruled out because although HSV causes recurrent oral and genital ulcers, it does not explain the recurrent uveitis and pathergy phenomenon (skin lesions at sites of trauma) described here, which together point to Behcet's disease.$x$, 1),
('e6000000-0000-0000-0000-000000000050', 'B', 'Reactive arthritis', false, 'Ruled out because reactive arthritis follows a specific gastrointestinal or genitourinary infection and causes arthritis, conjunctivitis, and urethritis, not this pattern of recurrent oral/genital ulcers with uveitis and pathergy.', 2),
('e6000000-0000-0000-0000-000000000050', 'C', $x$Behcet's disease$x$, true, $x$Correct. Recurrent oral and genital ulceration, anterior uveitis, and skin lesions developing at sites of minor trauma (positive pathergy phenomenon) in a patient of Turkish or Eastern Mediterranean/Middle Eastern/East Asian background (along the historic 'Silk Road' distribution) is classic for Behcet's disease, a variable-vessel vasculitis.$x$, 3),
('e6000000-0000-0000-0000-000000000050', 'D', 'Systemic lupus erythematosus', false, $x$Ruled out because although SLE can cause oral ulcers, it does not typically cause genital ulcers, recurrent uveitis, or a positive pathergy phenomenon, which are much more specific for Behcet's disease.$x$, 4),
('e6000000-0000-0000-0000-000000000050', 'E', 'Coeliac disease', false, 'Ruled out because coeliac disease can occasionally cause oral aphthous ulceration but does not cause genital ulcers, uveitis, or pathergy, and would be investigated with serology/duodenal biopsy rather than this clinical pattern.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('e6000000-0000-0000-0000-000000000001', 'Malar (butterfly) rash sparing the nasolabial folds, photosensitivity, oral ulcers, and non-erosive small-joint arthritis with cytopenias are core clinical features of SLE.', 1),
('e6000000-0000-0000-0000-000000000001', 'A positive ANA is sensitive but not specific for SLE; anti-dsDNA (and anti-Sm) are more specific and anti-dsDNA titre tracks disease activity, especially lupus nephritis.', 2),
('e6000000-0000-0000-0000-000000000001', 'Cytopenias (leucopenia, thrombocytopenia, haemolytic anaemia) are part of the SLE classification criteria and reflect autoantibody-mediated destruction.', 3),
('e6000000-0000-0000-0000-000000000002', 'Antiphospholipid syndrome causes venous or arterial thrombosis and recurrent pregnancy loss, and is diagnosed by combining clinical criteria with persistently positive antiphospholipid antibodies on two occasions at least 12 weeks apart.', 1),
('e6000000-0000-0000-0000-000000000002', 'Lupus anticoagulant paradoxically prolongs the APTT in vitro (by interfering with phospholipid-dependent clotting assays) while promoting thrombosis in vivo; failure of the APTT to correct on mixing studies suggests an inhibitor rather than a factor deficiency.', 2),
('e6000000-0000-0000-0000-000000000002', 'Antiphospholipid syndrome can be primary or secondary to SLE; women with a history of thrombosis require long-term anticoagulation, and pregnancy typically requires aspirin plus low-molecular-weight heparin under specialist care.', 3),
('e6000000-0000-0000-0000-000000000003', $x$Systemic sclerosis features Raynaud's phenomenon, sclerodactyly/skin tightening, and microstomia; diffuse cutaneous disease carries a higher risk of internal organ involvement including renal crisis and interstitial lung disease.$x$, 1),
('e6000000-0000-0000-0000-000000000003', 'Scleroderma renal crisis presents with abrupt severe hypertension, acute kidney injury, and microangiopathic haemolytic anaemia (schistocytes); it is a medical emergency treated urgently with ACE inhibitors regardless of baseline renal function.', 2),
('e6000000-0000-0000-0000-000000000003', 'Corticosteroids, especially in high doses, are a recognised trigger for scleroderma renal crisis and should be used cautiously (if at all) in patients with diffuse systemic sclerosis.', 3),
('e6000000-0000-0000-0000-000000000004', $x$Primary Sjogren's syndrome causes sicca symptoms (keratoconjunctivitis sicca and xerostomia) and is associated with anti-Ro (SSA) and anti-La (SSB) antibodies.$x$, 1),
('e6000000-0000-0000-0000-000000000004', $x$Sjogren's syndrome carries a markedly increased risk of B-cell non-Hodgkin lymphoma, particularly of the parotid glands; persistent gland swelling or new lymphadenopathy warrants further investigation.$x$, 2),
('e6000000-0000-0000-0000-000000000004', $x$Sjogren's syndrome can occur alone (primary) or secondary to other connective tissue diseases such as rheumatoid arthritis or SLE.$x$, 3),
('e6000000-0000-0000-0000-000000000005', $x$Dermatomyositis causes symmetrical proximal muscle weakness with a raised CK, plus characteristic skin signs: heliotrope rash (periorbital violaceous discolouration) and Gottron's papules over the knuckles/extensor surfaces.$x$, 1),
('e6000000-0000-0000-0000-000000000005', 'Dermatomyositis (and to a lesser extent polymyositis) is a recognised paraneoplastic phenomenon in adults; new-onset disease, especially over age 40, warrants thorough malignancy screening.', 2),
('e6000000-0000-0000-0000-000000000005', 'Dermatomyositis can also involve the lungs (interstitial lung disease), which should be assessed clinically and with pulmonary function tests/imaging as part of the work-up.', 3),
('e6000000-0000-0000-0000-000000000006', 'Drug-induced lupus is classically caused by hydralazine, procainamide, isoniazid, and minocycline, and typically presents with arthralgia and serositis rather than renal or CNS disease.', 1),
('e6000000-0000-0000-0000-000000000006', 'Anti-histone antibodies are characteristic of drug-induced lupus, while anti-dsDNA and anti-Sm (more specific for idiopathic SLE) are usually negative.', 2),
('e6000000-0000-0000-0000-000000000006', 'The mainstay of management is withdrawal of the causative drug, after which symptoms typically resolve over weeks to months; severe cases may need short-term NSAIDs or low-dose steroids.', 3),
('e6000000-0000-0000-0000-000000000007', 'Podagra (acute gouty monoarthritis of the first MTP joint) is a classic presentation of gout, often precipitated by alcohol, dehydration, or thiazide diuretics.', 1),
('e6000000-0000-0000-0000-000000000007', 'Any acutely hot, swollen joint must have septic arthritis actively excluded by joint aspiration with Gram stain and culture before assuming a diagnosis of gout, even when crystals are seen, because the two conditions can coexist.', 2),
('e6000000-0000-0000-0000-000000000007', 'Gout synovial fluid shows negatively birefringent needle-shaped monosodium urate crystals under polarised light microscopy, in contrast to the positively birefringent rhomboid crystals of pseudogout (CPPD).', 3),
('e6000000-0000-0000-0000-000000000008', 'NSAIDs should be avoided or used with extreme caution in patients with significant renal impairment or cardiovascular disease due to nephrotoxicity and cardiovascular risk.', 1),
('e6000000-0000-0000-0000-000000000008', 'Colchicine requires substantial dose reduction in renal impairment because of accumulation and toxicity risk; corticosteroids are a useful alternative first-line option for acute gout when NSAIDs and colchicine are contraindicated or poorly tolerated.', 2),
('e6000000-0000-0000-0000-000000000008', 'Urate-lowering therapy (e.g. allopurinol) should never be started during an acute flare; it is introduced only after the attack has resolved, typically with concurrent colchicine or NSAID cover to prevent a flare on initiation.', 3),
('e6000000-0000-0000-0000-000000000009', 'Calcium pyrophosphate deposition disease (pseudogout) typically affects the knee in elderly patients and is associated with hyperparathyroidism, haemochromatosis, hypothyroidism, and hypomagnesaemia.', 1),
('e6000000-0000-0000-0000-000000000009', 'Radiographic chondrocalcinosis (linear calcification of joint cartilage) supports a diagnosis of CPPD, though it can also be an incidental finding.', 2),
('e6000000-0000-0000-0000-000000000009', 'Synovial fluid microscopy differentiates gout (negatively birefringent needle-shaped urate crystals) from pseudogout (positively birefringent rhomboid-shaped calcium pyrophosphate crystals).', 3),
('e6000000-0000-0000-0000-000000000010', 'Urate-lowering therapy is indicated for recurrent gout flares, tophi, urate nephropathy, or renal stones, and should be started during a quiescent period, not during an acute attack.', 1),
('e6000000-0000-0000-0000-000000000010', 'Allopurinol is started at a low dose and titrated upward against serum urate (target usually <300 micromol/L), with colchicine or NSAID prophylaxis for the first 3-6 months to reduce flare risk during initiation.', 2),
('e6000000-0000-0000-0000-000000000010', 'HLA-B*5801 testing may be considered before starting allopurinol in patients of certain ethnic backgrounds (e.g. Han Chinese, Thai, Korean) due to increased risk of severe hypersensitivity reactions.', 3),
('e6000000-0000-0000-0000-000000000011', 'Any acutely hot, swollen, systemically unwell joint must be treated as septic arthritis until excluded, especially in patients with diabetes, immunosuppression, or prosthetic joints, who are at higher risk.', 1),
('e6000000-0000-0000-0000-000000000011', 'Management of suspected septic arthritis requires urgent joint aspiration before (or without delaying) empirical intravenous antibiotics, plus orthopaedic input for possible surgical washout.', 2),
('e6000000-0000-0000-0000-000000000011', 'Diabetes mellitus increases the risk of septic arthritis and its complications; a lower threshold for suspicion and urgent action is required in these patients.', 3),
('e6000000-0000-0000-0000-000000000012', 'Febuxostat is an alternative xanthine oxidase inhibitor to allopurinol, used when allopurinol is not tolerated or contraindicated (e.g. due to hypersensitivity or renal impairment considerations).', 1),
('e6000000-0000-0000-0000-000000000012', 'Febuxostat carries a boxed warning for increased cardiovascular mortality compared with allopurinol in patients with established cardiovascular disease, and should be used with caution and shared decision-making in this population.', 2),
('e6000000-0000-0000-0000-000000000012', 'Any new urate-lowering therapy should be covered with colchicine or NSAID prophylaxis initially to reduce the risk of precipitating an acute flare.', 3),
('e6000000-0000-0000-0000-000000000013', 'Rheumatoid arthritis classically causes symmetrical small-joint polyarthritis affecting the MCP, PIP and MTP joints while sparing the DIP joints, with morning stiffness lasting over an hour.', 1),
('e6000000-0000-0000-0000-000000000013', 'Anti-CCP antibodies are highly specific for rheumatoid arthritis and are associated with a more erosive disease course; rheumatoid factor is more sensitive but less specific.', 2),
('e6000000-0000-0000-0000-000000000013', 'Early diagnosis and referral to rheumatology for disease-modifying therapy is important, as early treatment reduces the risk of joint damage and disability.', 3),
('e6000000-0000-0000-0000-000000000014', 'Methotrexate requires regular monitoring of FBC, liver function tests, and renal function throughout treatment because of risks of bone marrow suppression, hepatotoxicity, and drug accumulation in renal impairment.', 1),
('e6000000-0000-0000-0000-000000000014', 'Methotrexate is given once weekly (not daily) with folic acid supplementation to reduce side effects; accidental daily dosing is a serious and potentially fatal prescribing error.', 2),
('e6000000-0000-0000-0000-000000000014', 'Patients should be counselled to seek urgent medical review for symptoms of infection, unexplained bruising/bleeding, or breathlessness/cough, which may indicate marrow suppression or pneumonitis.', 3),
('e6000000-0000-0000-0000-000000000015', 'DMARDs and biologics are immunosuppressive and are typically withheld temporarily during significant acute infections, then restarted once the patient has recovered.', 1),
('e6000000-0000-0000-0000-000000000015', 'Patients on methotrexate should be counselled to seek medical advice promptly if they develop fever, sore throat, or other signs of infection, given the risk of both increased susceptibility and bone marrow suppression.', 2),
('e6000000-0000-0000-0000-000000000015', $x$Decisions to hold or restart DMARDs during intercurrent illness should involve the patient's rheumatology team where possible, particularly for more complex or recurrent scenarios.$x$, 3),
('e6000000-0000-0000-0000-000000000016', 'Anti-TNF biologics carry a significant risk of reactivating latent tuberculosis and viral hepatitis B/C; screening (chest X-ray, IGRA/Mantoux, hepatitis serology) is mandatory before starting treatment.', 1),
('e6000000-0000-0000-0000-000000000016', 'If latent TB is identified, it should be treated before or alongside starting the biologic, under specialist guidance, to reduce the risk of reactivation.', 2),
('e6000000-0000-0000-0000-000000000016', 'Patients on biologics should be counselled about increased general infection risk and advised to seek prompt medical review for any new signs of infection.', 3),
('e6000000-0000-0000-0000-000000000017', 'Longstanding rheumatoid arthritis can cause erosive cervical spine disease, particularly atlantoaxial subluxation, risking spinal cord compression with neck movement.', 1),
('e6000000-0000-0000-0000-000000000017', $x$Symptoms such as neck pain, stiffness, or Lhermitte's sign (electric shock sensations down the limbs on neck flexion) should prompt cervical spine imaging before any procedure involving neck manipulation, including intubation.$x$, 2),
('e6000000-0000-0000-0000-000000000017', 'Anaesthetic teams must be alerted to known or suspected cervical spine instability in RA patients so that airway management can be adapted (e.g. awake fibreoptic intubation) to avoid neck hyperextension.', 3),
('e6000000-0000-0000-0000-000000000018', 'Accidental daily (rather than weekly) methotrexate dosing is a serious, potentially fatal prescribing/administration error that causes severe pancytopenia and mucositis.', 1),
('e6000000-0000-0000-0000-000000000018', 'Folinic acid (calcium folinate) rescue is the specific antidote for methotrexate toxicity and should be given urgently in overdose, distinct from routine folic acid supplementation used to reduce side effects of correctly-dosed methotrexate.', 2),
('e6000000-0000-0000-0000-000000000018', 'Patients newly started on methotrexate (and after any pharmacy or packaging change) should have dosing clearly and repeatedly explained, as dosing errors are a recognised and preventable cause of serious harm.', 3),
('e6000000-0000-0000-0000-000000000019', 'A DEXA T-score of -2.5 or below at the hip or spine defines osteoporosis; a fragility fracture (from a fall at standing height or less) is itself diagnostic of osteoporosis regardless of T-score.', 1),
('e6000000-0000-0000-0000-000000000019', 'Oral bisphosphonates (e.g. alendronic acid, risedronate) are first-line pharmacological treatment for osteoporosis, alongside ensuring adequate calcium and vitamin D intake.', 2),
('e6000000-0000-0000-0000-000000000019', 'Postmenopausal women are at increased risk of osteoporosis due to oestrogen deficiency accelerating bone resorption.', 3),
('e6000000-0000-0000-0000-000000000020', 'Osteomalacia results from vitamin D deficiency causing defective bone mineralisation, presenting with diffuse bone pain, proximal myopathy, and a biochemical picture of low calcium, low phosphate, and raised ALP.', 1),
('e6000000-0000-0000-0000-000000000020', 'Risk factors for vitamin D deficiency include reduced sun exposure (covering clothing, limited outdoor time, darker skin pigmentation), malabsorption, and chronic kidney or liver disease.', 2),
('e6000000-0000-0000-0000-000000000020', 'Treatment is with vitamin D replacement (colecalciferol) and calcium supplementation as needed, which typically resolves symptoms and normalises biochemistry over weeks to months.', 3),
('e6000000-0000-0000-0000-000000000021', $x$Paget's disease of bone causes localised areas of increased, disorganised bone turnover, presenting with bone pain, deformity, or incidental isolated marked elevation of ALP with otherwise normal calcium and phosphate.$x$, 1),
('e6000000-0000-0000-0000-000000000021', 'Classic sites include the pelvis, skull (leading to increasing hat size), spine, and long bones, with a characteristic mixed lytic-sclerotic appearance and cortical thickening on X-ray.', 2),
('e6000000-0000-0000-0000-000000000021', 'Complications include pathological fracture, deafness (skull involvement), high-output cardiac failure, and rarely malignant transformation to osteosarcoma.', 3),
('e6000000-0000-0000-0000-000000000022', 'Bisphosphonate-related osteonecrosis of the jaw is a rare but serious complication, particularly associated with invasive dental procedures performed after starting treatment, high-dose intravenous bisphosphonates (e.g. in cancer), and poor dental hygiene.', 1),
('e6000000-0000-0000-0000-000000000022', 'Good dental hygiene and completion of any necessary invasive dental work before starting bisphosphonates reduces this risk.', 2),
('e6000000-0000-0000-0000-000000000022', 'Patients on bisphosphonates should also be counselled about the rare risk of atypical femoral fractures with long-term use, and treatment duration should be periodically reviewed.', 3),
('e6000000-0000-0000-0000-000000000023', 'Primary hyperparathyroidism is characterised by raised calcium with an inappropriately normal or raised PTH (rather than suppressed), often with low phosphate, most commonly due to a solitary parathyroid adenoma.', 1),
('e6000000-0000-0000-0000-000000000023', $x$The classic symptom complex of primary hyperparathyroidism is remembered as 'bones (pain), stones (renal calculi), groans (abdominal symptoms/constipation), and moans (psychiatric symptoms such as depression or cognitive slowing).'$x$, 2),
('e6000000-0000-0000-0000-000000000023', 'Definitive treatment for symptomatic primary hyperparathyroidism or significant hypercalcaemia is usually parathyroidectomy.', 3),
('e6000000-0000-0000-0000-000000000024', 'Long-term corticosteroid use (generally prednisolone 7.5 mg/day or more for 3 months or longer) is a major risk factor for osteoporosis and warrants formal fracture risk assessment and DEXA scanning.', 1),
('e6000000-0000-0000-0000-000000000024', 'Bisphosphonate prophylaxis is often recommended alongside calcium and vitamin D in patients on long-term steroids who are at significant fracture risk, particularly in older patients or those with additional risk factors.', 2),
('e6000000-0000-0000-0000-000000000024', 'Steroid doses should always be tapered gradually rather than stopped abruptly to avoid adrenal insufficiency and disease flare.', 3),
('e6000000-0000-0000-0000-000000000025', 'Osteoarthritis typically causes activity-related joint pain with brief morning stiffness (<30 minutes), crepitus, and X-ray findings of joint space narrowing, osteophytes, subchondral sclerosis, and subchondral cysts.', 1),
('e6000000-0000-0000-0000-000000000025', 'First-line management of osteoarthritis is conservative: weight loss, exercise/physiotherapy, and simple analgesia, with intra-articular steroid injections or joint replacement reserved for refractory cases.', 2),
('e6000000-0000-0000-0000-000000000025', 'Osteoarthritis is a degenerative rather than autoimmune inflammatory process, so DMARDs and biologics have no role in its management.', 3),
('e6000000-0000-0000-0000-000000000026', 'Simple mechanical low back pain without red flag features (no neurological deficit, no systemic symptoms) is managed conservatively with advice to stay active, simple analgesia, and does not require imaging.', 1),
('e6000000-0000-0000-0000-000000000026', 'Red flags for back pain that would change management include: saddle anaesthesia, bladder/bowel dysfunction, bilateral leg weakness (cauda equina), fever, unexplained weight loss, history of malignancy, or significant trauma.', 2),
('e6000000-0000-0000-0000-000000000026', 'Bed rest is not recommended for mechanical back pain, as it can prolong recovery and increase disability; early mobilisation is encouraged.', 3),
('e6000000-0000-0000-0000-000000000027', 'Cauda equina syndrome red flags include saddle anaesthesia, bladder or bowel dysfunction (retention or incontinence), bilateral leg weakness/pain, and reduced anal tone; any of these in a patient with back pain warrants emergency assessment.', 1),
('e6000000-0000-0000-0000-000000000027', 'Cauda equina syndrome most commonly results from a large central lumbar disc herniation compressing multiple nerve roots below the level of the spinal cord.', 2),
('e6000000-0000-0000-0000-000000000027', 'Management is emergency MRI whole spine and, if confirmed, urgent surgical decompression; delay significantly worsens the chance of recovering bladder, bowel, and motor function.', 3),
('e6000000-0000-0000-0000-000000000028', 'Red flags for back pain requiring urgent investigation include unexplained weight loss, night sweats, fever, history of malignancy, age over 50 with new back pain, and progressive neurological symptoms.', 1),
('e6000000-0000-0000-0000-000000000028', 'Spinal metastases can present with back pain alone before neurological deficit develops; early identification and urgent MRI are important to prevent progression to metastatic spinal cord compression.', 2),
('e6000000-0000-0000-0000-000000000028', 'Prostate, breast, lung, renal, and thyroid cancers are the most common sources of bony metastases, and a history of any of these should heighten suspicion in a patient presenting with new back pain.', 3),
('e6000000-0000-0000-0000-000000000029', 'Total joint replacement is considered when osteoarthritis causes significant pain and functional impairment despite an adequate trial of conservative management (analgesia, weight loss, physiotherapy).', 1),
('e6000000-0000-0000-0000-000000000029', 'Reduced internal rotation is a classic early examination finding in hip osteoarthritis.', 2),
('e6000000-0000-0000-0000-000000000029', 'Intra-articular corticosteroid injections can provide short-term symptomatic relief but are not a substitute for definitive surgical management in advanced, refractory disease.', 3),
('e6000000-0000-0000-0000-000000000030', 'Neurogenic claudication (from lumbar spinal stenosis) is classically relieved by sitting or leaning forward (spinal flexion), unlike vascular claudication, which is relieved simply by stopping and standing still.', 1),
('e6000000-0000-0000-0000-000000000030', 'A normal ankle-brachial pressure index and normal peripheral pulses argue against significant peripheral arterial disease as the cause of exertional leg pain.', 2),
('e6000000-0000-0000-0000-000000000030', 'Lumbar spinal stenosis is common in older adults and often coexists with degenerative lumbar spine disease; MRI is the investigation of choice to confirm canal narrowing.', 3),
('e6000000-0000-0000-0000-000000000031', 'Inflammatory back pain (young age of onset, morning stiffness >30-60 minutes, improvement with exercise, worse with rest, and good response to NSAIDs) distinguishes ankylosing spondylitis from mechanical back pain.', 1),
('e6000000-0000-0000-0000-000000000031', 'HLA-B27 is strongly associated with ankylosing spondylitis, though it is not diagnostic alone as it is also present in a proportion of the healthy population.', 2),
('e6000000-0000-0000-0000-000000000031', 'Sacroiliitis (erosions and sclerosis of the sacroiliac joints) on X-ray or MRI is a key diagnostic feature of ankylosing spondylitis.', 3),
('e6000000-0000-0000-0000-000000000032', $x$Dactylitis (diffuse 'sausage' swelling of an entire digit due to combined synovitis and tenosynovitis) is a hallmark feature of psoriatic arthritis.$x$, 1),
('e6000000-0000-0000-0000-000000000032', 'Psoriatic arthritis is associated with nail changes (pitting, onycholysis), and can affect any pattern of joints (asymmetrical oligoarthritis, symmetrical polyarthritis, DIP-predominant, spondylitis, or arthritis mutilans).', 2),
('e6000000-0000-0000-0000-000000000032', 'Psoriatic arthritis is typically seronegative (rheumatoid factor and anti-CCP negative), distinguishing it serologically from rheumatoid arthritis.', 3),
('e6000000-0000-0000-0000-000000000033', 'Reactive arthritis classically follows gastrointestinal infection (Campylobacter, Salmonella, Shigella, Yersinia) or genitourinary infection (Chlamydia) by 1-4 weeks.', 1),
('e6000000-0000-0000-0000-000000000033', $x$The classic triad is remembered as 'can't see (conjunctivitis/uveitis), can't pee (urethritis), can't climb a tree (arthritis)', though not all three features are always present.$x$, 2),
('e6000000-0000-0000-0000-000000000033', 'Reactive arthritis is typically self-limiting over weeks to months but can occasionally become chronic or recurrent; management is with NSAIDs and treatment of any persistent underlying infection.', 3),
('e6000000-0000-0000-0000-000000000034', $x$Enteropathic arthritis is a peripheral or axial arthritis occurring in patients with inflammatory bowel disease (Crohn's disease or ulcerative colitis), classified as a seronegative spondyloarthropathy.$x$, 1),
('e6000000-0000-0000-0000-000000000034', 'Peripheral enteropathic arthritis activity often parallels bowel disease activity, whereas axial involvement (spondylitis) tends to follow an independent course.', 2),
('e6000000-0000-0000-0000-000000000034', 'Management focuses on treating the underlying IBD, which often improves the peripheral arthritis; NSAIDs should be used cautiously in IBD as they can exacerbate bowel symptoms.', 3),
('e6000000-0000-0000-0000-000000000035', 'Acute anterior uveitis is a recognised extra-articular manifestation of ankylosing spondylitis (and other spondyloarthropathies), presenting with a painful red eye, photophobia, blurred vision, and an irregular pupil.', 1),
('e6000000-0000-0000-0000-000000000035', 'Any patient with a spondyloarthropathy presenting with a painful red eye requires same-day ophthalmology assessment given the risk of sight-threatening complications if uveitis is not promptly treated.', 2),
('e6000000-0000-0000-0000-000000000035', 'Treatment of acute anterior uveitis typically involves topical corticosteroids and mydriatic/cycloplegic drops under ophthalmology supervision.', 3),
('e6000000-0000-0000-0000-000000000036', $x$The 'pencil-in-cup' deformity is a classic radiographic finding of severe psoriatic arthritis, caused by erosive resorption of one side of a joint with tapering of the adjacent bone.$x$, 1),
('e6000000-0000-0000-0000-000000000036', 'Psoriatic arthritis characteristically affects the distal interphalangeal joints (unlike rheumatoid arthritis, which spares them), often alongside nail changes and dactylitis.', 2),
('e6000000-0000-0000-0000-000000000036', 'Severe, destructive psoriatic arthritis can progress to arthritis mutilans, causing significant digital shortening and deformity if not adequately treated.', 3),
('e6000000-0000-0000-0000-000000000037', 'A painful arc of movement (pain within a specific mid-range of abduction, typically 60-120 degrees, with less pain outside this range) is characteristic of subacromial impingement/rotator cuff tendinopathy.', 1),
('e6000000-0000-0000-0000-000000000037', 'Frozen shoulder (adhesive capsulitis) is distinguished by globally restricted active AND passive range of movement in all planes, unlike impingement, which preserves passive movement.', 2),
('e6000000-0000-0000-0000-000000000037', 'Initial management of subacromial impingement is conservative: activity modification, physiotherapy, and analgesia/NSAIDs, with subacromial corticosteroid injection considered if conservative measures fail.', 3),
('e6000000-0000-0000-0000-000000000038', 'Adhesive capsulitis (frozen shoulder) causes global restriction of both active and passive shoulder movement, distinguishing it from rotator cuff pathology and impingement, which preserve passive range of movement.', 1),
('e6000000-0000-0000-0000-000000000038', 'Diabetes mellitus is a well-recognised risk factor for frozen shoulder, and diabetic patients may have a more prolonged and resistant course.', 2),
('e6000000-0000-0000-0000-000000000038', 'Frozen shoulder typically progresses through three phases: painful freezing, stiff frozen, and thawing, with the overall course often lasting 1-3 years even without intervention.', 3),
('e6000000-0000-0000-0000-000000000039', $x$Lateral epicondylitis ('tennis elbow') causes lateral elbow pain reproduced by resisted wrist extension, resulting from repetitive overuse of the common extensor tendon origin.$x$, 1),
('e6000000-0000-0000-0000-000000000039', $x$Medial epicondylitis ('golfer's elbow') is the analogous condition on the medial side, reproduced by resisted wrist flexion.$x$, 2),
('e6000000-0000-0000-0000-000000000039', 'Management is typically conservative: activity modification, physiotherapy, and analgesia, with steroid injection or other interventions considered for persistent symptoms.', 3),
('e6000000-0000-0000-0000-000000000040', $x$Plantar fasciitis classically causes heel pain worst with the first steps in the morning or after rest ('start-up pain'), easing somewhat with continued activity, with tenderness at the medial calcaneal tubercle.$x$, 1),
('e6000000-0000-0000-0000-000000000040', 'Risk factors include running/repetitive impact activity, obesity, and prolonged standing.', 2),
('e6000000-0000-0000-0000-000000000040', 'Management is conservative: stretching exercises, appropriate footwear/orthotics, and analgesia, with most cases resolving over several months.', 3),
('e6000000-0000-0000-0000-000000000041', $x$De Quervain's tenosynovitis affects the first dorsal compartment tendons (abductor pollicis longus and extensor pollicis brevis) and is diagnosed clinically with a positive Finkelstein test.$x$, 1),
('e6000000-0000-0000-0000-000000000041', 'It is common in new parents due to repetitive lifting of infants with the wrist in radial deviation and thumb abduction, and also occurs with other repetitive thumb/wrist activities.', 2),
('e6000000-0000-0000-0000-000000000041', 'Management is typically conservative: activity modification, splinting, and analgesia, with corticosteroid injection considered for persistent symptoms.', 3),
('e6000000-0000-0000-0000-000000000042', $x$Complete Achilles tendon rupture classically presents with a sudden 'pop' during forceful push-off activity (e.g. sprinting, jumping), a palpable gap in the tendon, and weakness of plantarflexion.$x$, 1),
('e6000000-0000-0000-0000-000000000042', 'The Simmonds (Thompson) calf squeeze test is positive (no plantarflexion of the foot on squeezing the calf) when the Achilles tendon is completely ruptured, due to loss of continuity between the muscle and the foot.', 2),
('e6000000-0000-0000-0000-000000000042', 'Achilles tendon rupture requires urgent orthopaedic referral; management may be surgical repair or conservative immobilisation in an equinus cast, depending on patient factors and local practice.', 3),
('e6000000-0000-0000-0000-000000000043', 'Carpal tunnel syndrome causes numbness/tingling in the median nerve distribution (thumb, index, middle, and radial half of ring finger), classically worse at night and relieved by shaking the hand.', 1),
('e6000000-0000-0000-0000-000000000043', $x$Positive Tinel's sign (tapping over the median nerve at the wrist reproduces symptoms) and Phalen's test (sustained wrist flexion reproduces symptoms) support the clinical diagnosis.$x$, 2),
('e6000000-0000-0000-0000-000000000043', 'Pregnancy, hypothyroidism, rheumatoid arthritis, diabetes, and repetitive wrist activity are recognised risk factors for carpal tunnel syndrome; pregnancy-related cases often resolve after delivery.', 3),
('e6000000-0000-0000-0000-000000000044', 'Giant cell arteritis presents with new temporal headache, scalp tenderness, jaw claudication, and systemic symptoms in patients typically over 50, with markedly raised ESR/CRP.', 1),
('e6000000-0000-0000-0000-000000000044', 'GCA is a medical emergency due to the risk of sudden irreversible visual loss (from anterior ischaemic optic neuropathy); high-dose corticosteroids must be started immediately on clinical suspicion, without waiting for biopsy confirmation.', 2),
('e6000000-0000-0000-0000-000000000044', 'Temporal artery biopsy should be arranged promptly (ideally within 1 week of starting steroids) to confirm the diagnosis, but treatment should never be delayed while awaiting this.', 3),
('e6000000-0000-0000-0000-000000000045', 'Amaurosis fugax (transient visual loss) in a patient with GCA is a warning sign of impending permanent visual loss and requires emergency escalation of treatment.', 1),
('e6000000-0000-0000-0000-000000000045', 'Visual loss occurring despite oral corticosteroid treatment for GCA requires urgent intravenous methylprednisolone and same-day ophthalmology assessment to protect the remaining (or fellow) eye.', 2),
('e6000000-0000-0000-0000-000000000045', 'Once visual loss has occurred in GCA, it is often irreversible; the priority of emergency treatment is protecting remaining vision rather than reversing loss that has already happened.', 3),
('e6000000-0000-0000-0000-000000000046', 'Polymyalgia rheumatica causes bilateral shoulder and hip girdle pain and stiffness, worse in the morning, typically in patients over 50, with raised ESR/CRP but no true muscle weakness or CK elevation.', 1),
('e6000000-0000-0000-0000-000000000046', 'PMR is closely associated with giant cell arteritis; patients with PMR should be asked specifically about headache, scalp tenderness, jaw claudication, or visual symptoms at every review.', 2),
('e6000000-0000-0000-0000-000000000046', 'PMR shows a rapid and dramatic symptomatic response to low-dose corticosteroids (e.g. prednisolone 15mg daily), which supports the diagnosis when present.', 3),
('e6000000-0000-0000-0000-000000000047', 'Takayasu arteritis is a large-vessel vasculitis affecting the aorta and its major branches, classically presenting in young women with limb claudication, absent or asymmetrical pulses, and blood pressure discrepancies between limbs.', 1),
('e6000000-0000-0000-0000-000000000047', 'Bruits over affected large vessels (e.g. subclavian, carotid) and raised inflammatory markers support the diagnosis, which is confirmed with vascular imaging (CT/MR angiography).', 2),
('e6000000-0000-0000-0000-000000000047', 'Management typically involves corticosteroids with consideration of additional immunosuppressive or biologic therapy, and vascular surgical intervention for critical stenoses.', 3),
('e6000000-0000-0000-0000-000000000048', 'Granulomatosis with polyangiitis is an ANCA-associated small-vessel vasculitis classically involving the upper respiratory tract (sinusitis, saddle nose deformity), lower respiratory tract (haemoptysis, pulmonary nodules), and kidneys (rapidly progressive glomerulonephritis).', 1),
('e6000000-0000-0000-0000-000000000048', 'cANCA with anti-proteinase 3 (PR3) antibodies is strongly associated with granulomatosis with polyangiitis, whereas pANCA/anti-MPO is more associated with microscopic polyangiitis and eosinophilic granulomatosis with polyangiitis.', 2),
('e6000000-0000-0000-0000-000000000048', 'Early recognition and urgent rheumatology/renal referral is essential, as untreated ANCA-associated vasculitis with renal involvement can rapidly progress to end-stage renal failure and is life-threatening.', 3),
('e6000000-0000-0000-0000-000000000049', 'Henoch-Schonlein purpura (IgA vasculitis) classically presents in children with palpable purpura (typically buttocks/lower limbs), abdominal pain, arthritis/arthralgia, and renal involvement, often following an upper respiratory tract infection.', 1),
('e6000000-0000-0000-0000-000000000049', 'Renal involvement (haematuria, proteinuria) should be monitored closely, as a minority of children develop significant nephritis requiring specialist follow-up; most cases are otherwise self-limiting.', 2),
('e6000000-0000-0000-0000-000000000049', 'HSP is a small-vessel vasculitis mediated by IgA immune complex deposition, distinguishing it pathologically from ANCA-associated vasculitides.', 3),
('e6000000-0000-0000-0000-000000000050', $x$Behcet's disease is a variable-vessel vasculitis characterised by recurrent oral and genital ulceration, uveitis, and skin lesions, with increased prevalence along the historic Silk Road (Turkey, Middle East, East Asia).$x$, 1),
('e6000000-0000-0000-0000-000000000050', $x$The pathergy phenomenon (development of a skin lesion or pustule at a site of minor trauma, such as a needle prick) is a characteristic and supportive diagnostic feature of Behcet's disease.$x$, 2),
('e6000000-0000-0000-0000-000000000050', $x$Behcet's disease can also cause more severe manifestations including large vessel vasculitis, thrombosis, and neurological involvement (neuro-Behcet's), requiring specialist immunosuppressive management.$x$, 3);
